    registeredSellers.push(seller);
  }
  // 3. Primary Test: No filters
  const noFilterResult = await api.functional.shoppingMall.admin.sellers.index(
    adminConnection,
    {
      body: {} satisfies IShoppingMallSeller.IRequest,
    },
