    "product id matches",
    updatedImage.shopping_mall_product_id,
    product.id,
  );
  TestValidator.equals("url updated to new value", updatedImage.url, newUrl);
  TestValidator.equals(
    "sequence unchanged",
    updatedImage.sequence,
    originalSequence,
  );
  TestValidator.equals(
    "created_at preserved",
    updatedImage.created_at,
    originalCreatedAt,
  );
}

