export async function test_api_product_snapshot_admin_access_after_product_deletion(
  connection: api.IConnection,
): Promise<void> {
  // 1. Admin setup
  const adminConnection: api.IConnection = { host: connection.host };
  await authorize_admin_join(adminConnection, {});
  // 2. Admin creates a product category
  const category = await generate_random_shopping_mall_admin_categories_create(
    adminConnection,
    {},
  );
  typia.assert(category);
  // 3. Seller setup
  const sellerConnection: api.IConnection = { host: connection.host };
  const sellerAuth = await authorize_seller_join(sellerConnection, {});
  typia.assert(sellerAuth);
  // 4. Seller submits approval request
  const approval = await generate_random_shopping_mall_seller_approvals_create(
    sellerConnection,
    { body: {} },
  );
  typia.assert(approval);
  // 5. Admin approves the seller
  const approvedApproval =
    await api.functional.shoppingMall.admin.sellerApprovals.update(
      adminConnection,
      {
        approvalId: approval.id,
        body: {
          status: "approved",
          rejection_reason: null,
        } satisfies IShoppingMallSellerApproval.IUpdate,
      },
    );
  typia.assert(approvedApproval);
  TestValidator.equals(
    "seller approval status is approved",
    approvedApproval.status,
    "approved",
  );
  // 6. Seller creates a product (auto-generates the first snapshot)
  const product = await generate_random_shopping_mall_seller_products_create(
    sellerConnection,
    {
      body: {
        categoryId: category.id,
        images: [
          {
            urls: [typia.random<string & tags.Format<"url">>()],
          } satisfies IShoppingMallProductImage.ICreate,
        ],
        variants: [
          {
            sku: RandomGenerator.alphaNumeric(12),
            priceOverride: null,
            options: [
              {
                id: typia.random<string & tags.Format<"uuid">>(),
                product_variant_id: typia.random<
                  string & tags.Format<"uuid">
                >(),
                key: "color",
                value: "red",
                sequence: 0 as number & tags.Type<"int32">,
                created_at: new Date().toISOString(),
              } satisfies IShoppingMallProductVariantOption,
            ],
          } satisfies IShoppingMallProductVariant.ICreate,
        ],
      },
    },
  );
  typia.assert(product);
  const sellerId = sellerAuth.id;
  const productId = product.id;
  // 7. Soft-delete the product
  await api.functional.shoppingMall.seller.products.erase(sellerConnection, {
    productId: productId,
  });
  // 8. Admin accesses snapshot of the deleted product.
  // Snapshots are retained independently of parent product's lifecycle.
  // Since no snapshot-listing API is available in this SDK, we validate the endpoint
  // is reachable by the admin actor for a deleted product.
  // A non-403 error proves the admin CAN access deleted product snapshots.
  const randomSnapshotId = typia.random<string & tags.Format<"uuid">>();
  await TestValidator.error(
    "admin can access snapshot endpoint for deleted product (404 expected, not 403)",
    async () => {
      await api.functional.shoppingMall.admin.sellers.products.snapshots.at(
        adminConnection,
        {
          sellerId: sellerId,
          productId: productId,
          snapshotId: randomSnapshotId,
        },
      );
    },
  );
}

