    customerConnection,
    { body: addressBody },
  );
  typia.assert(address);
  const addressId = address.id;
  // 4. As admin, retrieve the address detail
  const retrieved =
    await api.functional.shoppingMall.admin.customers.addresses.at(
      adminConnection,
      {
        customerId,
        addressId,
