export async function test_api_wishlist_item_detail_retrieval_by_owner(
  connection: api.IConnection,
): Promise<void> {
  // 1. Admin setup - create admin connection and register
  const adminConnection: api.IConnection = { host: connection.host };
  await authorize_admin_join(adminConnection, {});
  // 2. Create a product category (admin-authenticated)
  const category = await generate_random_shopping_mall_admin_categories_create(
    adminConnection,
    {
      body: {
        name: RandomGenerator.alphabets(8),
        description: RandomGenerator.paragraph({ sentences: 2 }),
        parent_id: null,
      },
    },
  );
  typia.assert(category);
  // 3. Seller setup - create seller connection and register
  const sellerConnection: api.IConnection = { host: connection.host };
  const sellerAuth = await authorize_seller_join(sellerConnection, {});
  typia.assert(sellerAuth);
  // 4. Create a product (seller-authenticated), passing only categoryId;
  //    the utility function handles random generation of name, description,
  //    base_price, images, and variants.
  const product = await generate_random_shopping_mall_seller_products_create(
    sellerConnection,
    {
      body: {
        categoryId: category.id,
      },
    },
  );
  typia.assert(product);
  // 5. Customer setup - create customer connection and register
  const customerConnection: api.IConnection = { host: connection.host };
  await authorize_customer_join(customerConnection, {});
  // 6. Add the product to the customer's wishlist
  const wishlistItem =
    await generate_random_shopping_mall_customer_wishlist_items_create(
      customerConnection,
      {
        body: {
          shopping_mall_product_id: product.id,
        },
      },
    );
  typia.assert(wishlistItem);
  // Main test: retrieve the specific wishlist item by its ID
  const retrieved = await api.functional.shoppingMall.customer.wishlistItems.at(
    customerConnection,
    {
      wishlistItemId: wishlistItem.id,
    },
  );
  typia.assert(retrieved);
  // Validate: id matches the wishlist item ID from creation
  TestValidator.equals(
    "wishlist item id matches",
    retrieved.id,
    wishlistItem.id,
  );
  // Validate: product id matches the product created by the seller
  TestValidator.equals("product id matches", retrieved.product.id, product.id);
  // Validate: product name matches
  TestValidator.equals(
    "product name matches",
    retrieved.product.name,
    product.name,
  );
  // Validate: product base_price matches
  TestValidator.equals(
    "product base_price matches",
    retrieved.product.base_price,
    product.base_price,
  );
  // Validate: seller shopName matches
  TestValidator.equals(
    "product seller shopName matches",
    retrieved.product.seller.shopName,
    sellerAuth.shopName,
  );
  // Validate: product is active (deleted_at is null)
  TestValidator.equals(
    "product is active (deleted_at is null)",
    retrieved.product.deleted_at,
    null,
  );
}

