export async function test_api_cart_item_detail_retrieval_available(
  connection: api.IConnection,
): Promise<void> {
  // 1. Register admin account
  const adminConnection: api.IConnection = { host: connection.host };
  await authorize_admin_join(adminConnection, {});
  // 2. Register seller account
  const sellerConnection: api.IConnection = { host: connection.host };
  await authorize_seller_join(sellerConnection, {
    body: {
      email: typia.random<string & tags.Format<"email">>(),
      password: RandomGenerator.alphaNumeric(16),
      shop_name: RandomGenerator.name(),
      href: typia.random<string & tags.Format<"uri">>(),
      referrer: typia.random<string & tags.Format<"uri">>(),
    },
  });
  // 3. Seller submits approval request
  const approval = await generate_random_shopping_mall_seller_approvals_create(
    sellerConnection,
    { body: {} },
  );
  typia.assert(approval);
  // 4. Admin approves the seller
  const approvedApproval =
    await api.functional.shoppingMall.admin.sellerApprovals.update(
      adminConnection,
      {
        approvalId: approval.id,
        body: {
          status: "approved",
          rejection_reason: null,
        } satisfies IShoppingMallSellerApproval.IUpdate,
      },
    );
  typia.assert(approvedApproval);
  // 5. Admin creates a category
  const category = await generate_random_shopping_mall_admin_categories_create(
    adminConnection,
    {},
  );
  typia.assert(category);
  // 6. Seller creates a product with base_price = 10000
  const product = await generate_random_shopping_mall_seller_products_create(
    sellerConnection,
    {
      body: {
        name: RandomGenerator.paragraph({ sentences: 2 }),
        description: RandomGenerator.paragraph({ sentences: 3 }),
        base_price: 10000,
        categoryId: category.id,
      },
    },
  );
  typia.assert(product);
  // 7. Seller adds a variant with options color:Blue, size:M, no priceOverride
  const variant =
    await generate_random_shopping_mall_seller_products_variants_create(
      sellerConnection,
      {
        params: { productId: product.id },
        body: {
          sku: `SKU-${RandomGenerator.alphaNumeric(12)}`,
          priceOverride: null,
          options: [
            { key: "color", value: "Blue", sequence: 0 },
            { key: "size", value: "M", sequence: 1 },
          ],
        },
      },
    );
  typia.assert(variant);
  // 8. Seller adds 10 units of inventory to the variant
  const inventoryRecord =
    await generate_random_shopping_mall_seller_products_variants_inventory_records_create(
      sellerConnection,
      {
        params: { productId: product.id, variantId: variant.id },
        body: {
          quantity: 10,
          note: "Initial stock",
        },
      },
    );
  typia.assert(inventoryRecord);
  // 9. Register a customer account
  const customerConnection: api.IConnection = { host: connection.host };
  await authorize_customer_join(customerConnection, {});
  // 10. Customer adds the variant to cart with quantity=3
  const cartItem =
    await generate_random_shopping_mall_customer_cart_items_create(
      customerConnection,
      {
        body: {
          product_variant_id: variant.id,
          quantity: 3,
        },
      },
    );
  typia.assert(cartItem);
  // Test execution: GET /shoppingMall/customer/cartItems/{cartItemId}
  const retrieved = await api.functional.shoppingMall.customer.cartItems.at(
    customerConnection,
    { cartItemId: cartItem.id },
  );
  typia.assert(retrieved);
  // Validations
  TestValidator.equals("cart item id matches", retrieved.id, cartItem.id);
  TestValidator.equals(
    "productVariant id matches",
    retrieved.productVariant.id,
    variant.id,
  );
  TestValidator.equals("quantity is 3", retrieved.quantity, 3);
  TestValidator.equals(
    "unitPrice equals base_price 10000",
    retrieved.unitPrice,
    10000,
  );
  TestValidator.equals("subtotal equals 30000", retrieved.subtotal, 30000);
  TestValidator.equals(
    "availabilityStatus is available",
    retrieved.availabilityStatus,
    "available",
  );
  TestValidator.equals("stockWarning is false", retrieved.stockWarning, false);
}

