export async function test_api_cart_item_duplicate_variant_quantity_consolidation(
  connection: api.IConnection,
): Promise<void> {
  // 1. Admin setup
  const adminConnection: api.IConnection = { host: connection.host };
  await authorize_admin_join(adminConnection, {});
  // 2. Seller setup
  const sellerConnection: api.IConnection = { host: connection.host };
  await authorize_seller_join(sellerConnection, {});
  // 3. Seller submits approval request
  const approval = await generate_random_shopping_mall_seller_approvals_create(
    sellerConnection,
    { body: {} },
  );
  typia.assert(approval);
  // 4. Admin approves the seller
  const approvedApproval =
    await api.functional.shoppingMall.admin.sellerApprovals.update(
      adminConnection,
      {
        approvalId: approval.id,
        body: {
          status: "approved",
          rejection_reason: null,
        } satisfies IShoppingMallSellerApproval.IUpdate,
      },
    );
  typia.assert(approvedApproval);
  // 5. Admin creates a product category
  const category = await generate_random_shopping_mall_admin_categories_create(
    adminConnection,
    {},
  );
  typia.assert(category);
  // 6. Seller creates a product
  const product = await generate_random_shopping_mall_seller_products_create(
    sellerConnection,
    {
      body: {
        categoryId: category.id,
      },
    },
  );
  typia.assert(product);
  // 7. Seller adds a variant with at least one option
  const variant =
    await generate_random_shopping_mall_seller_products_variants_create(
      sellerConnection,
      {
        params: { productId: product.id },
        body: {},
      },
    );
  typia.assert(variant);
  // 8. Seller adds inventory stock (20 units) so the variant is 'available'
  const inventoryRecord =
    await generate_random_shopping_mall_seller_products_variants_inventory_records_create(
      sellerConnection,
      {
        params: { productId: product.id, variantId: variant.id },
        body: {
          quantity: 20 as number & tags.Type<"int32">,
          note: "Initial stock for cart consolidation test",
        },
      },
    );
  typia.assert(inventoryRecord);
  // 9. Customer joins the platform
  const customerConnection: api.IConnection = { host: connection.host };
  await authorize_customer_join(customerConnection, {});
  // FIRST ADD: Add 2 units of the variant to the cart
  const firstCartItem =
    await generate_random_shopping_mall_customer_cart_items_create(
      customerConnection,
      {
        body: {
          product_variant_id: variant.id,
          quantity: 2 as number & tags.Type<"int32"> & tags.Minimum<1>,
        },
      },
    );
  typia.assert(firstCartItem);
  // Validate first cart item quantity
  TestValidator.equals("first cart item quantity", firstCartItem.quantity, 2);
  const firstCartItemId = firstCartItem.id;
  // SECOND ADD: Add 3 more units of the same variant to the cart
  const secondCartItem =
    await generate_random_shopping_mall_customer_cart_items_create(
      customerConnection,
      {
        body: {
          product_variant_id: variant.id,
          quantity: 3 as number & tags.Type<"int32"> & tags.Minimum<1>,
        },
      },
    );
  typia.assert(secondCartItem);
  // Validate upsert behavior: same id (no duplicate entry created)
  TestValidator.equals(
    "cart item id is the same after second add (upsert, no duplicate)",
    secondCartItem.id,
    firstCartItemId,
  );
  // Validate quantity consolidation: 2 + 3 = 5
  TestValidator.equals(
    "consolidated quantity is 5 (2 + 3)",
    secondCartItem.quantity,
    5,
  );
  // Validate availability status remains 'available'
  TestValidator.equals(
    "availability status is available",
    secondCartItem.availabilityStatus,
    "available",
  );
  // Validate stock warning is false (stock 20 >= quantity 5)
  TestValidator.equals(
    "stockWarning is false (sufficient stock)",
    secondCartItem.stockWarning,
    false,
  );
  // Validate subtotal = unitPrice * consolidated quantity
  TestValidator.equals(
    "subtotal equals unitPrice * 5",
    secondCartItem.subtotal,
    secondCartItem.unitPrice * 5,
  );
  // Validate updatedAt >= createdAt (confirming an update occurred)
  TestValidator.predicate(
    "updatedAt is later than or equal to createdAt",
    new Date(secondCartItem.updatedAt) >= new Date(secondCartItem.createdAt),
  );
}

