export async function test_api_order_detail_snapshot_immutability_after_product_update(
  connection: api.IConnection,
): Promise<void> {
  // 1. Admin setup: register admin and create category
  const adminConnection: api.IConnection = { host: connection.host };
  await authorize_admin_join(adminConnection, {});
  const category = await generate_random_shopping_mall_admin_categories_create(
    adminConnection,
    {
      body: {
        name: "Test Category " + RandomGenerator.alphabets(6),
        description: "Category for snapshot immutability test",
      },
    },
  );
  typia.assert(category);
  // 2. Seller setup: register seller
  const sellerPassword = RandomGenerator.alphaNumeric(16);
  const sellerEmail = typia.random<string & tags.Format<"email">>();
  const originalShopName = "Shop-" + RandomGenerator.alphabets(8);
  const sellerConnection: api.IConnection = { host: connection.host };
  await authorize_seller_join(sellerConnection, {
    body: {
      email: sellerEmail,
      password: sellerPassword,
      shop_name: originalShopName,
    },
  });
  // 3. Seller submits approval request
  const approvalRequest =
    await generate_random_shopping_mall_seller_approvals_create(
      sellerConnection,
      { body: {} },
    );
  typia.assert(approvalRequest);
  // 4. Admin approves the seller
  const approvedApproval =
    await api.functional.shoppingMall.admin.sellerApprovals.update(
      adminConnection,
      {
        approvalId: approvalRequest.id,
        body: {
          status: "approved",
          rejection_reason: null,
        } satisfies IShoppingMallSellerApproval.IUpdate,
      },
    );
  typia.assert(approvedApproval);
  // 5. Seller creates product with 'Original Product Name'
  const originalProductName = "Original Product Name";
  const originalBasePrice = 50000;
  const product = await generate_random_shopping_mall_seller_products_create(
    sellerConnection,
    {
      body: {
        name: originalProductName,
        description: "A test product for snapshot immutability verification",
        base_price: originalBasePrice,
        categoryId: category.id,
      },
    },
  );
  typia.assert(product);
  // 6. Seller creates variant with SKU 'SKU-ORIGINAL'
  const originalSkuCode = "SKU-ORIGINAL";
  const variant =
    await generate_random_shopping_mall_seller_products_variants_create(
      sellerConnection,
      {
        params: { productId: product.id },
        body: {
          sku: originalSkuCode,
          priceOverride: null,
          options: [
            {
              id: typia.random<string & tags.Format<"uuid">>(),
              product_variant_id: typia.random<string & tags.Format<"uuid">>(),
              key: "size",
              value: "M",
              sequence: 0,
              created_at: new Date().toISOString(),
            },
          ],
        },
      },
    );
  typia.assert(variant);
  // 7. Seller adds inventory for the variant
  const inventoryRecord =
    await generate_random_shopping_mall_seller_products_variants_inventory_records_create(
      sellerConnection,
      {
        params: {
          productId: product.id,
          variantId: variant.id,
        },
        body: {
          quantity: 100,
          note: "Initial stock for testing",
        },
      },
    );
  typia.assert(inventoryRecord);
  // 8. Customer registers and places an order
  const customerConnection: api.IConnection = { host: connection.host };
  await authorize_customer_join(customerConnection, {});
  const order = await generate_random_shopping_mall_customer_orders_create(
    customerConnection,
    {
      body: {
        recipient_name: RandomGenerator.name(),
        recipient_phone: RandomGenerator.mobile(),
        shipping_address_line1: "123 Test Street",
        shipping_address_line2: null,
        shipping_city: "Seoul",
        shipping_state: "Gyeonggi",
        shipping_postal_code: "12345",
        shipping_country: "KR",
        items: [
          {
            product_variant_id: variant.id,
            quantity: 1,
          },
        ],
      },
    },
  );
  typia.assert(order);
  // 9. Seller updates the product's name to 'Updated Product Name'
  const updatedProduct =
    await api.functional.shoppingMall.seller.products.update(sellerConnection, {
      productId: product.id,
      body: {
        name: "Updated Product Name",
      } satisfies IShoppingMallProduct.IUpdate,
    });
  typia.assert(updatedProduct);
  // Confirm the product name was updated
  TestValidator.equals(
    "product name updated on live record",
    updatedProduct.name,
    "Updated Product Name",
  );
  // 10. Customer retrieves order detail - snapshot must be immutable
  const orderDetail = await api.functional.shoppingMall.customer.orders.at(
    customerConnection,
    {
      orderId: order.id,
    },
  );
  typia.assert(orderDetail);
  // 11. Verify snapshot immutability assertions
  TestValidator.predicate(
    "order has at least one item",
    orderDetail.items.length > 0,
  );
  const firstItem = orderDetail.items[0];
  typia.assertGuard(firstItem!);
  // Verify product snapshot preserves original name
  TestValidator.equals(
    "snapshot product name equals original at purchase time",
    firstItem.snapshot.productSnapshot.name,
    originalProductName,
  );
  // Verify SKU snapshot preserves original SKU code
  TestValidator.equals(
    "snapshot SKU code equals original",
    firstItem.snapshot.productSnapshotSku.skuCode,
    originalSkuCode,
  );
  // Verify seller profile snapshot preserves original shop name
  TestValidator.equals(
    "snapshot seller shop name equals original shop name at order time",
    firstItem.snapshot.sellerProfileSnapshot.shopName,
    originalShopName,
  );
  // Verify base price preserved in snapshot
  TestValidator.equals(
    "snapshot base price equals original price at purchase time",
    firstItem.snapshot.productSnapshot.basePrice,
    originalBasePrice,
  );
}

