export async function test_api_order_creation_banned_customer_rejected(
  connection: api.IConnection,
): Promise<void> {
  // 1. Admin setup
  const adminConnection: api.IConnection = { host: connection.host };
  await authorize_admin_join(adminConnection, {});
  // 2. Admin creates a product category
  const category = await generate_random_shopping_mall_admin_categories_create(
    adminConnection,
    {},
  );
  typia.assert(category);
  // 3. Seller setup
  const sellerConnection: api.IConnection = { host: connection.host };
  await authorize_seller_join(sellerConnection, {});
  // 4. Seller submits an approval request
  const approval = await generate_random_shopping_mall_seller_approvals_create(
    sellerConnection,
    {},
  );
  typia.assert(approval);
  // 5. Admin approves the seller
  const approvedApproval =
    await api.functional.shoppingMall.admin.sellerApprovals.update(
      adminConnection,
      {
        approvalId: approval.id,
        body: {
          status: "approved",
          rejection_reason: null,
        } satisfies IShoppingMallSellerApproval.IUpdate,
      },
    );
  typia.assert(approvedApproval);
  // 6. Seller creates a product
  const product = await generate_random_shopping_mall_seller_products_create(
    sellerConnection,
    {
      body: {
        categoryId: category.id,
      },
    },
  );
  typia.assert(product);
  // 7. Seller creates a product variant
  const variant =
    await generate_random_shopping_mall_seller_products_variants_create(
      sellerConnection,
      {
        params: {
          productId: product.id,
        },
      },
    );
  typia.assert(variant);
  // 8. Seller stocks the variant with inventory
  const inventoryRecord =
    await generate_random_shopping_mall_seller_products_variants_inventory_records_create(
      sellerConnection,
      {
        body: {
          quantity: 100 as number & tags.Type<"int32">,
          note: "Initial stock for test",
        },
        params: {
          productId: product.id,
          variantId: variant.id,
        },
      },
    );
  typia.assert(inventoryRecord);
  // 9. Customer registers
  const customerConnection: api.IConnection = { host: connection.host };
  const customerSession = await authorize_customer_join(customerConnection, {});
  typia.assert(customerSession);
  // 10. Admin bans the customer
  const bannedCustomer = await api.functional.shoppingMall.admin.customers.ban(
    adminConnection,
    {
      customerId: customerSession.id,
    },
  );
  typia.assert(bannedCustomer);
  TestValidator.equals("customer is banned", bannedCustomer.isBanned, true);
  // 11. Attempt to place an order with the banned customer's connection (should fail)
  const orderBody = {
    recipient_name: RandomGenerator.name(),
    recipient_phone: RandomGenerator.mobile(),
    shipping_address_line1: "123 Test Street",
    shipping_address_line2: null,
    shipping_city: "Test City",
    shipping_state: "Test State",
    shipping_postal_code: "12345",
    shipping_country: "US",
    items: [
      {
        product_variant_id: variant.id,
        quantity: typia.random<
          number & tags.Type<"int32"> & tags.Minimum<1> & tags.Maximum<5>
        >(),
      },
    ],
  } satisfies IShoppingMallOrder.ICreate;
  await TestValidator.error("banned customer cannot place order", async () => {
    await api.functional.shoppingMall.customer.orders.create(
      customerConnection,
      {
        body: orderBody,
      },
    );
  });
  // 12. Confirm consistent rejection on repeated attempts
  await TestValidator.error(
    "banned customer cannot place order (repeated attempt)",
    async () => {
      await api.functional.shoppingMall.customer.orders.create(
        customerConnection,
        {
          body: orderBody,
        },
      );
    },
  );
}

