  await authorize_customer_join(customerBConnection, {});
  // Test: Customer B attempts to access Customer A's order items — must be denied with 403
  await TestValidator.error(
    "Customer B cannot access Customer A's order items",
    async () => {
      await api.functional.shoppingMall.customer.orders.items.index(
        customerBConnection,
        {
          orderId: order.id,
          body: {} satisfies IShoppingMallOrderItem.IRequest,
        },
      );
    },
  );
}

