  typia.assert(inventoryRecord);
  // ── Step 9: Register a Customer ───────────────────────────────────────────
  const customerConnection: api.IConnection = { host: connection.host };
  await authorize_customer_join(customerConnection, {});
  // ── Step 10: Customer places an order ─────────────────────────────────────
  const order = await generate_random_shopping_mall_customer_orders_create(
    customerConnection,
    {
      body: {
        recipient_name: RandomGenerator.name(),
        recipient_phone: RandomGenerator.mobile(),
        shipping_address_line1: "123 Test Street",
        shipping_address_line2: null,
        shipping_city: "Seoul",
        shipping_state: null,
        shipping_postal_code: "12345",
        shipping_country: "KR",
        items: [
          {
            product_variant_id: variant.id,
            quantity: 1,
          },
        ],
      },
    },
  );
  typia.assert(order);
  // ── Step 11: Seller A creates a shipment for the order ───────────────────
  const orderItemId = order.items[0]!.id;
  const shipment =
    await generate_random_shopping_mall_seller_orders_shipments_create(
      sellerAConnection,
      {
        params: { orderId: order.id },
        body: {
          carrier: "FedEx",
          trackingNumber: RandomGenerator.alphaNumeric(16),
          orderItemIds: [orderItemId],
          shippedAt: new Date().toISOString(),
          estimatedDeliveryAt: new Date(
            Date.now() + 7 * 24 * 60 * 60 * 1000,
          ).toISOString(),
        },
      },
    );
  typia.assert(shipment);
  // ── Step 12: Register Seller B ────────────────────────────────────────────
  const sellerBConnection: api.IConnection = { host: connection.host };
  await authorize_seller_join(sellerBConnection, {
    body: {
      email: typia.random<string & tags.Format<"email">>(),
      password: RandomGenerator.alphaNumeric(16),
      shop_name: RandomGenerator.name(),
      href: typia.random<string & tags.Format<"uri">>(),
      referrer: typia.random<string & tags.Format<"uri">>(),
    },
  });
  // ── Target Operation: Seller B attempts to update Seller A's shipment ────
  // This must be rejected with 403 or 404 because Seller B does not own the shipment
  await TestValidator.httpError(
    "seller B cannot update seller A's shipment",
    [403, 404],
    async () => {
      await api.functional.shoppingMall.seller.orders.shipments.update(
        sellerBConnection,
        {
          orderId: order.id,
          shipmentId: shipment.id,
          body: {
            carrier: "DHL",
            tracking_number: RandomGenerator.alphaNumeric(16),
            shipped_at: new Date().toISOString(),
            estimated_delivery_at: new Date(
              Date.now() + 5 * 24 * 60 * 60 * 1000,
            ).toISOString(),
          } satisfies IShoppingMallShipment.IUpdate,
        },
      );
    },
  );
}

