  typia.assert(order);
  // Collect the paid order item IDs
  const paidItemIds = order.items
    .filter((item) => item.status === "paid")
    .map((item) => item.id);
  TestValidator.predicate("order has paid items", paidItemIds.length > 0);
  // ── 11. Seller creates a shipment ─────────────────────────────────────
  const shipment =
    await generate_random_shopping_mall_seller_orders_shipments_create(
      sellerConnection,
      {
        params: { orderId: order.id },
        body: {
          carrier: "FedEx",
          trackingNumber: RandomGenerator.alphaNumeric(12),
          orderItemIds: paidItemIds,
          shippedAt: new Date().toISOString(),
        },
      },
    );
  typia.assert(shipment);
  // ── Target Action: Seller deletes the shipment ────────────────────────
  await api.functional.shoppingMall.seller.orders.shipments.erase(
    sellerConnection,
    {
      orderId: order.id,
      shipmentId: shipment.id,
    },
  );
  // ── Assertion: Trying to delete again should fail ─────────────────────
  await TestValidator.error(
    "deleting already-deleted shipment should fail",
    async () => {
      await api.functional.shoppingMall.seller.orders.shipments.erase(
        sellerConnection,
        {
          orderId: order.id,
          shipmentId: shipment.id,
        },
      );
    },
  );
}

