export async function test_api_shipment_items_listing_by_seller(
  connection: api.IConnection,
): Promise<void> {
  // ─── 1. Admin Setup ───────────────────────────────────────────────────────
  const adminConnection: api.IConnection = { host: connection.host };
  await authorize_admin_join(adminConnection, {});
  // ─── 2. Seller Registration ───────────────────────────────────────────────
  const sellerEmail = typia.random<string & tags.Format<"email">>();
  const sellerPassword = RandomGenerator.alphaNumeric(16);
  const sellerShopName = RandomGenerator.name();
  const sellerConnection: api.IConnection = { host: connection.host };
  await authorize_seller_join(sellerConnection, {
    body: {
      email: sellerEmail,
      password: sellerPassword,
      shop_name: sellerShopName,
      href: typia.random<string & tags.Format<"uri">>(),
      referrer: typia.random<string & tags.Format<"uri">>(),
    },
  });
  // ─── 3. Admin creates a product category ─────────────────────────────────
  const category = await generate_random_shopping_mall_admin_categories_create(
    adminConnection,
    {},
  );
  typia.assert(category);
  // ─── 4. Seller submits approval request ──────────────────────────────────
  const approval = await generate_random_shopping_mall_seller_approvals_create(
    sellerConnection,
    { body: {} },
  );
  typia.assert(approval);
  // ─── 5. Admin approves the seller ────────────────────────────────────────
  const updatedApproval =
    await api.functional.shoppingMall.admin.sellerApprovals.update(
      adminConnection,
      {
        approvalId: approval.id,
        body: {
          status: "approved",
          rejection_reason: null,
        } satisfies IShoppingMallSellerApproval.IUpdate,
      },
    );
  typia.assert(updatedApproval);
  // ─── 6. Seller creates a product ─────────────────────────────────────────
  const productName = RandomGenerator.paragraph({ sentences: 2 });
  const product = await generate_random_shopping_mall_seller_products_create(
    sellerConnection,
    {
      body: {
        name: productName,
        description: RandomGenerator.paragraph({ sentences: 3 }),
        base_price: 10000,
        categoryId: category.id,
      },
    },
  );
  typia.assert(product);
  // ─── 7. Seller adds a product variant ────────────────────────────────────
  const variantSku = `SKU-${RandomGenerator.alphaNumeric(8)}`;
  const variantOption = typia.random<IShoppingMallProductVariantOption>();
  const variant =
    await generate_random_shopping_mall_seller_products_variants_create(
      sellerConnection,
      {
        params: { productId: product.id },
        body: {
          sku: variantSku,
          priceOverride: 10000,
          options: [
            {
              ...variantOption,
              key: "color",
              value: "red",
              sequence: 0,
            },
          ],
        },
      },
    );
  typia.assert(variant);
  // ─── 8. Seller adds inventory ────────────────────────────────────────────
  const inventoryRecord =
    await generate_random_shopping_mall_seller_products_variants_inventory_records_create(
      sellerConnection,
      {
        params: { productId: product.id, variantId: variant.id },
        body: {
          quantity: 50,
          note: "Initial stock for testing",
        },
      },
    );
  typia.assert(inventoryRecord);
  // ─── 9. Register a customer ───────────────────────────────────────────────
  const customerConnection: api.IConnection = { host: connection.host };
  await authorize_customer_join(customerConnection, {});
  // ─── 10. Customer places an order ────────────────────────────────────────
  const orderQuantity = 2;
  const order = await generate_random_shopping_mall_customer_orders_create(
    customerConnection,
    {
      body: {
        recipient_name: RandomGenerator.name(),
        recipient_phone: RandomGenerator.mobile(),
        shipping_address_line1: "123 Test Street",
        shipping_address_line2: null,
        shipping_city: "Seoul",
        shipping_state: null,
        shipping_postal_code: "12345",
        shipping_country: "KR",
        items: [
          {
            product_variant_id: variant.id,
            quantity: orderQuantity,
          },
        ],
      },
    },
  );
  typia.assert(order);
  // Get the first order item id
  const orderItem = order.items[0];
  typia.assertGuard(orderItem!);
  // ─── 11. Seller creates a shipment (which also assigns the order item) ────
  // The shipment creation includes orderItemIds and automatically creates
  // the shipment item junction records, transitioning order item status to 'shipped'.
  const shipment =
    await generate_random_shopping_mall_seller_orders_shipments_create(
      sellerConnection,
      {
        params: { orderId: order.id },
        body: {
          carrier: "TestCarrier",
          trackingNumber: `TRACK-${RandomGenerator.alphaNumeric(10)}`,
          orderItemIds: [orderItem.id],
          shippedAt: new Date().toISOString(),
          estimatedDeliveryAt: null,
        },
      },
    );
  typia.assert(shipment);
  // ─── Test Execution: List shipment items (default pagination) ─────────────
  const listResult =
    await api.functional.shoppingMall.seller.orders.shipments.items.index(
      sellerConnection,
      {
        orderId: order.id,
        shipmentId: shipment.id,
        body: {} satisfies IShoppingMallShipmentItem.IRequest,
      },
    );
  typia.assert(listResult);
  // ─── Validations ──────────────────────────────────────────────────────────
  TestValidator.equals(
    "records count",
    listResult.pagination.records as number,
    1,
  );
  TestValidator.equals(
    "current page",
    listResult.pagination.current as number,
    1,
  );
  TestValidator.equals("data length", listResult.data.length, 1);
  const firstItem = listResult.data[0];
  typia.assertGuard(firstItem!);
  TestValidator.equals(
    "order item status is shipped",
    firstItem.orderItem.status,
    "shipped",
  );
  TestValidator.equals(
    "order item quantity matches",
    firstItem.orderItem.quantity as number,
    orderQuantity,
  );
  TestValidator.equals(
    "snapshot product name matches",
    firstItem.orderItem.snapshot.productSnapshot.name,
    productName,
  );
  TestValidator.equals(
    "snapshot seller shop name matches",
    firstItem.orderItem.snapshot.sellerProfileSnapshot.shopName,
    sellerShopName,
  );
  TestValidator.equals(
    "snapshot sku code matches",
    firstItem.orderItem.snapshot.productSnapshotSku.skuCode,
    variantSku,
  );
  // ─── Edge Case: Empty page beyond records ─────────────────────────────────
  const emptyPageResult =
    await api.functional.shoppingMall.seller.orders.shipments.items.index(
      sellerConnection,
      {
        orderId: order.id,
        shipmentId: shipment.id,
        body: {
          page: 2,
          limit: 100,
        } satisfies IShoppingMallShipmentItem.IRequest,
      },
    );
  typia.assert(emptyPageResult);
  TestValidator.equals(
    "edge case: records still 1",
    emptyPageResult.pagination.records as number,
    1,
  );
  TestValidator.equals(
    "edge case: pages is 1",
    emptyPageResult.pagination.pages as number,
    1,
  );
  TestValidator.equals(
    "edge case: current is 2",
    emptyPageResult.pagination.current as number,
    2,
  );
  TestValidator.equals(
    "edge case: empty data array",
    emptyPageResult.data.length,
    0,
  );
}

