export async function test_api_shipment_items_listing_filtered_by_status(
  connection: api.IConnection,
): Promise<void> {
  // 1. Register admin
  const adminConnection: api.IConnection = { host: connection.host };
  await authorize_admin_join(adminConnection, {});
  // 2. Register seller
  const sellerConnection: api.IConnection = { host: connection.host };
  await authorize_seller_join(sellerConnection, {
    body: {
      email: typia.random<string & tags.Format<"email">>(),
      password: RandomGenerator.alphaNumeric(16),
      shop_name: RandomGenerator.name(),
      href: typia.random<string & tags.Format<"uri">>(),
      referrer: typia.random<string & tags.Format<"uri">>(),
    },
  });
  // 3. Admin creates a product category
  const category = await generate_random_shopping_mall_admin_categories_create(
    adminConnection,
    {},
  );
  typia.assert(category);
  // 4. Seller submits approval request
  const approval = await generate_random_shopping_mall_seller_approvals_create(
    sellerConnection,
    {},
  );
  typia.assert(approval);
  // 5. Admin approves the seller
  const updatedApproval =
    await api.functional.shoppingMall.admin.sellerApprovals.update(
      adminConnection,
      {
        approvalId: approval.id,
        body: {
          status: "approved",
          rejection_reason: null,
        } satisfies IShoppingMallSellerApproval.IUpdate,
      },
    );
  typia.assert(updatedApproval);
  // 6. Seller creates a product
  const product = await generate_random_shopping_mall_seller_products_create(
    sellerConnection,
    {
      body: {
        categoryId: category.id,
      },
    },
  );
  typia.assert(product);
  // 7. Seller adds a variant
  const variant =
    await generate_random_shopping_mall_seller_products_variants_create(
      sellerConnection,
      {
        params: { productId: product.id },
      },
    );
  typia.assert(variant);
  // 8. Seller adds inventory stock
  const inventoryRecord =
    await generate_random_shopping_mall_seller_products_variants_inventory_records_create(
      sellerConnection,
      {
        params: {
          productId: product.id,
          variantId: variant.id,
        },
        body: {
          quantity: 10,
          note: "Initial stock for testing",
        },
      },
    );
  typia.assert(inventoryRecord);
  // 9. Register customer
  const customerConnection: api.IConnection = { host: connection.host };
  await authorize_customer_join(customerConnection, {});
  // 10. Customer places an order referencing the variant
  const order = await generate_random_shopping_mall_customer_orders_create(
    customerConnection,
    {
      body: {
        items: [
          {
            product_variant_id: variant.id,
            quantity: 1,
          },
        ],
      },
    },
  );
  typia.assert(order);
  // Get the order item id from the order
  const orderItem = order.items[0]!;
  const orderItemId = orderItem.id;
  // 11. Seller creates a shipment for the order and assigns the paid order item
  // (creating the shipment with orderItemIds transitions item status to 'shipped')
  const shipment =
    await generate_random_shopping_mall_seller_orders_shipments_create(
      sellerConnection,
      {
        params: { orderId: order.id },
        body: {
          orderItemIds: [orderItemId],
        },
      },
    );
  typia.assert(shipment);
  // Test Execution 1 - Filter by 'shipped'
  const shippedResult =
    await api.functional.shoppingMall.seller.orders.shipments.items.index(
      sellerConnection,
      {
        orderId: order.id,
        shipmentId: shipment.id,
        body: {
          status: "shipped",
        } satisfies IShoppingMallShipmentItem.IRequest,
      },
    );
  typia.assert(shippedResult);
  // Validate shipped filter results
  TestValidator.equals(
    "shipped filter records count",
    shippedResult.pagination.records,
    1,
  );
  TestValidator.predicate("all items have shipped status", () =>
    shippedResult.data.every((item) => item.orderItem.status === "shipped"),
  );
  // Test Execution 2 - Filter by 'paid'
  const paidResult =
    await api.functional.shoppingMall.seller.orders.shipments.items.index(
      sellerConnection,
      {
        orderId: order.id,
        shipmentId: shipment.id,
        body: {
          status: "paid",
        } satisfies IShoppingMallShipmentItem.IRequest,
      },
    );
  typia.assert(paidResult);
  // Validate paid filter results - should be empty since all items transitioned to shipped
  TestValidator.equals(
    "paid filter records count should be 0",
    paidResult.pagination.records,
    0,
  );
  TestValidator.equals(
    "paid filter data should be empty",
    paidResult.data.length,
    0,
  );
  TestValidator.equals(
    "paid filter pages should be 0",
    paidResult.pagination.pages,
    0,
  );
  // Test Execution 3 - Pagination with shipped filter (page=1, limit=1)
  const paginatedResult =
    await api.functional.shoppingMall.seller.orders.shipments.items.index(
      sellerConnection,
      {
        orderId: order.id,
        shipmentId: shipment.id,
        body: {
          status: "shipped",
          page: 1,
          limit: 1,
        } satisfies IShoppingMallShipmentItem.IRequest,
      },
    );
  typia.assert(paginatedResult);
  // Validate paginated results
  TestValidator.equals(
    "paginated limit equals 1",
    paginatedResult.pagination.limit,
    1,
  );
  TestValidator.equals(
    "paginated pages equals 1",
    paginatedResult.pagination.pages,
    1,
  );
  TestValidator.equals(
    "paginated data contains 1 item",
    paginatedResult.data.length,
    1,
  );
}

