    adminConnection,
    {
      approvalId: sellerBApproval.id,
      body: {
        status: "approved",
        rejection_reason: null,
      } satisfies IShoppingMallSellerApproval.IUpdate,
    },
  );
  // 7. Seller B attempts to access Seller A's shipment item -> must be rejected
  await TestValidator.httpError(
    "seller B cannot access seller A's shipment item",
    [403, 404],
    async () => {
      await api.functional.shoppingMall.seller.orders.shipments.items.at(
        sellerBConnection,
        {
          orderId: order.id,
          shipmentId: shipment.id,
          shipmentItemId: firstShipmentItem.id,
        },
      );
    },
  );
}

