            product_variant_id: variant.id,
            quantity: 1,
          },
        ],
      },
    },
  );
  typia.assert(order);
  // =========================================================================
  // Step 12: Seller A creates a shipment (assigning the paid order items)
  // =========================================================================
  const paidOrderItemIds = order.items
    .filter((item) => item.status === "paid")
    .map((item) => item.id);
  const shipment =
    await generate_random_shopping_mall_seller_orders_shipments_create(
      sellerAConnection,
      {
        params: { orderId: order.id },
        body: {
          carrier: "FedEx",
          trackingNumber: `TRACK-${RandomGenerator.alphaNumeric(10)}`,
          orderItemIds: paidOrderItemIds,
        },
      },
    );
  typia.assert(shipment);
  // =========================================================================
  // Step 13: Get the shipment item created during shipment creation
  // The shipment creation response includes the assigned shipment items
  // =========================================================================
  const shipmentItem = shipment.items[0];
  typia.assertGuard(shipmentItem!);
  // =========================================================================
  // Test: Seller B attempts to remove Seller A's shipment item
  // Expected: 403 Forbidden - seller isolation prevents cross-seller deletion
  // =========================================================================
  await TestValidator.error(
    "seller B cannot remove seller A's shipment item (seller isolation)",
    async () => {
      await api.functional.shoppingMall.seller.orders.shipments.items.erase(
        sellerBConnection,
        {
          orderId: order.id,
          shipmentId: shipment.id,
          shipmentItemId: shipmentItem.id,
        },
      );
    },
  );
  // =========================================================================
  // Verification: Seller A can successfully delete the same shipment item
  // This confirms the setup was valid and the block was specifically due to
  // seller isolation, not a general issue with the shipment item
  // =========================================================================
  await api.functional.shoppingMall.seller.orders.shipments.items.erase(
    sellerAConnection,
    {
      orderId: order.id,
      shipmentId: shipment.id,
      shipmentItemId: shipmentItem.id,
    },
  );
}

