export async function test_api_cancellation_request_retrieval_pending_status(
  connection: api.IConnection,
): Promise<void> {
  // 1. Admin join
  const adminConnection: api.IConnection = { host: connection.host };
  await authorize_admin_join(adminConnection, {});
  // 2. Admin creates a product category
  const category = await generate_random_shopping_mall_admin_categories_create(
    adminConnection,
    {},
  );
  typia.assert(category);
  // 3. Seller join
  const sellerConnection: api.IConnection = { host: connection.host };
  await authorize_seller_join(sellerConnection, {});
  // 4. Seller submits an approval request
  const approval = await generate_random_shopping_mall_seller_approvals_create(
    sellerConnection,
    {},
  );
  typia.assert(approval);
  // 5. Admin approves the seller
  const approvedApproval =
    await api.functional.shoppingMall.admin.sellerApprovals.update(
      adminConnection,
      {
        approvalId: approval.id,
        body: {
          status: "approved",
          rejection_reason: null,
        } satisfies IShoppingMallSellerApproval.IUpdate,
      },
    );
  typia.assert(approvedApproval);
  // 6. Seller creates a product using the category
  const product = await generate_random_shopping_mall_seller_products_create(
    sellerConnection,
    {
      body: {
        categoryId: category.id,
      },
    },
  );
  typia.assert(product);
  // 7. Seller adds a variant to the product
  const variant =
    await generate_random_shopping_mall_seller_products_variants_create(
      sellerConnection,
      {
        params: {
          productId: product.id,
        },
      },
    );
  typia.assert(variant);
  // 8. Seller records positive inventory (10 units)
  const inventoryRecord =
    await generate_random_shopping_mall_seller_products_variants_inventory_records_create(
      sellerConnection,
      {
        params: {
          productId: product.id,
          variantId: variant.id,
        },
        body: {
          quantity: 10,
          note: "Initial stock",
        },
      },
    );
  typia.assert(inventoryRecord);
  // 9. Customer join
  const customerConnection: api.IConnection = { host: connection.host };
  await authorize_customer_join(customerConnection, {});
  // 10. Customer places an order referencing the variant
  const order = await generate_random_shopping_mall_customer_orders_create(
    customerConnection,
    {
      body: {
        items: [
          {
            product_variant_id: variant.id,
            quantity: 1,
          },
        ],
      },
    },
  );
  typia.assert(order);
  // Extract the orderId and orderItemId from the order
  const orderId = order.id;
  const orderItem = order.items[0]!;
  const orderItemId = orderItem.id;
  // 11. Customer submits a cancellation request
  const cancellationReason = "I changed my mind and no longer need this item.";
  const cancellationRequest =
    await generate_random_shopping_mall_customer_orders_items_cancellation_requests_create(
      customerConnection,
      {
        params: {
          orderId,
          orderItemId,
        },
        body: {
          reason: cancellationReason,
        },
      },
    );
  typia.assert(cancellationRequest);
  // Target: GET cancellation request by ID
  const retrieved =
    await api.functional.shoppingMall.customer.orders.items.cancellationRequests.at(
      customerConnection,
      {
        orderId,
        orderItemId,
        cancellationRequestId: cancellationRequest.id,
      },
    );
  typia.assert(retrieved);
  // Validations
  TestValidator.equals(
    "cancellation request id matches",
    retrieved.id,
    cancellationRequest.id,
  );
  TestValidator.equals("status is pending", retrieved.status, "pending");
  TestValidator.equals(
    "reason matches submitted reason",
    retrieved.reason,
    cancellationReason,
  );
  TestValidator.equals(
    "snapshots is empty (no seller decision yet)",
    retrieved.snapshots.length,
    0,
  );
  TestValidator.equals(
    "orderItem id matches",
    retrieved.orderItem.id,
    orderItemId,
  );
  TestValidator.equals(
    "orderItem status is paid",
    retrieved.orderItem.status,
    "paid",
  );
}

