  // ── Test 3: No search filter returns both ─────────────────────────────
  const allResult =
    await api.functional.shoppingMall.customer.cancellationRequests.index(
      customerConnection,
      {
        body: {} satisfies IShoppingMallCancellationRequest.IRequest,
