  // ── Test 4: Nonexistent keyword returns empty ─────────────────────────
  const emptyResult =
    await api.functional.shoppingMall.customer.cancellationRequests.index(
      customerConnection,
      {
        body: {
          search: "nonexistent_keyword_xyz",
