export async function test_api_cancellation_request_seller_approval(
  connection: api.IConnection,
): Promise<void> {
  // ─── 1. Admin setup ───────────────────────────────────────────────────────
  const adminConnection: api.IConnection = { host: connection.host };
  await authorize_admin_join(adminConnection, {});
  // ─── 2. Seller setup ──────────────────────────────────────────────────────
  const sellerConnection: api.IConnection = { host: connection.host };
  await authorize_seller_join(sellerConnection, {});
  // ─── 3. Seller submits approval request ──────────────────────────────────
  const sellerApproval =
    await generate_random_shopping_mall_seller_approvals_create(
      sellerConnection,
      {},
    );
  typia.assert(sellerApproval);
  // ─── 4. Admin approves the seller's approval request ─────────────────────
  const approvedSellerApproval =
    await api.functional.shoppingMall.admin.sellerApprovals.update(
      adminConnection,
      {
        approvalId: sellerApproval.id,
        body: {
          status: "approved",
          rejection_reason: null,
        } satisfies IShoppingMallSellerApproval.IUpdate,
      },
    );
  typia.assert(approvedSellerApproval);
  TestValidator.equals(
    "seller approval status",
    approvedSellerApproval.status,
    "approved",
  );
  // ─── 5. Admin creates a product category ─────────────────────────────────
  const category = await generate_random_shopping_mall_admin_categories_create(
    adminConnection,
    {
      body: {
        name: RandomGenerator.alphabets(10),
      },
    },
  );
  typia.assert(category);
  // ─── 6. Seller creates a product ─────────────────────────────────────────
  const product = await generate_random_shopping_mall_seller_products_create(
    sellerConnection,
    {
      body: {
        name: RandomGenerator.paragraph({ sentences: 2 }),
        description: RandomGenerator.paragraph({ sentences: 3 }),
        base_price: 5000,
        categoryId: category.id,
      },
    },
  );
  typia.assert(product);
  // ─── 7. Seller creates a product variant ─────────────────────────────────
  const variant =
    await generate_random_shopping_mall_seller_products_variants_create(
      sellerConnection,
      {
        params: { productId: product.id },
        body: {
          sku: `SKU-${RandomGenerator.alphaNumeric(12)}`,
          priceOverride: null,
          options: [
            {
              key: "color",
              value: "red",
              sequence: 0,
            },
          ],
        },
      },
    );
  typia.assert(variant);
  // ─── 8. Seller adds inventory ─────────────────────────────────────────────
  const inventoryRecord =
    await generate_random_shopping_mall_seller_products_variants_inventory_records_create(
      sellerConnection,
      {
        params: {
          productId: product.id,
          variantId: variant.id,
        },
        body: {
          quantity: 100,
          note: "Initial stock for testing",
        },
      },
    );
  typia.assert(inventoryRecord);
  // ─── 9. Customer setup ────────────────────────────────────────────────────
  const customerConnection: api.IConnection = { host: connection.host };
  await authorize_customer_join(customerConnection, {});
  // ─── 10. Customer places an order ────────────────────────────────────────
  const order = await generate_random_shopping_mall_customer_orders_create(
    customerConnection,
    {
      body: {
        recipient_name: RandomGenerator.name(),
        recipient_phone: RandomGenerator.mobile(),
        shipping_address_line1: "123 Test Street",
        shipping_address_line2: null,
        shipping_city: "Seoul",
        shipping_state: null,
        shipping_postal_code: "12345",
        shipping_country: "KR",
        items: [
          {
            product_variant_id: variant.id,
            quantity: 1,
          },
        ],
      },
    },
  );
  typia.assert(order);
  // Get the first order item
  const orderItem = order.items[0]!;
  // ─── 11. Customer submits a cancellation request ──────────────────────────
  const cancellationReason = "I changed my mind about this purchase";
  const cancellationRequest =
    await generate_random_shopping_mall_customer_orders_items_cancellation_requests_create(
      customerConnection,
      {
        params: {
          orderId: order.id,
          orderItemId: orderItem.id,
        },
        body: {
          reason: cancellationReason,
        },
      },
    );
  typia.assert(cancellationRequest);
  TestValidator.equals(
    "initial cancellation status is pending",
    cancellationRequest.status,
    "pending",
  );
  // ─── 12. Main test - Seller approves the cancellation request ─────────────
  const approvedCancellation =
    await api.functional.shoppingMall.seller.cancellationRequests.update(
      sellerConnection,
      {
        cancellationRequestId: cancellationRequest.id,
        body: {
          status: "approved",
        } satisfies IShoppingMallCancellationRequest.IUpdate,
      },
    );
  typia.assert(approvedCancellation);
  // ─── 13. Validate the response ────────────────────────────────────────────
  // Status should be 'approved'
  TestValidator.equals(
    "cancellation request status after approval",
    approvedCancellation.status,
    "approved",
  );
  // updatedAt should be >= createdAt
  TestValidator.predicate(
    "updatedAt is more recent than or equal to createdAt",
    new Date(approvedCancellation.updatedAt) >=
      new Date(approvedCancellation.createdAt),
  );
  // Snapshots array should have exactly one entry
  TestValidator.equals(
    "snapshots count is exactly 1",
    approvedCancellation.snapshots.length,
    1,
  );
  // The snapshot should have status = 'approved'
  const snapshot = approvedCancellation.snapshots[0]!;
  TestValidator.equals(
    "snapshot status is approved",
    snapshot.status,
    "approved",
  );
  // The snapshot reason should match the original reason verbatim
  TestValidator.equals(
    "snapshot reason matches original customer reason",
    snapshot.reason,
    cancellationReason,
  );
  // The snapshot has a valid created_at
  TestValidator.predicate(
    "snapshot created_at is a valid date",
    !isNaN(new Date(snapshot.created_at).getTime()),
  );
}

