export async function test_api_cancellation_request_already_resolved_repeat_attempt(
  connection: api.IConnection,
): Promise<void> {
  // 1. Create admin connection and authenticate
  const adminConnection: api.IConnection = { host: connection.host };
  await authorize_admin_join(adminConnection, {});
  // 2. Create seller connection and authenticate
  const sellerConnection: api.IConnection = { host: connection.host };
  const sellerEmail = typia.random<string & tags.Format<"email">>();
  const sellerPassword = RandomGenerator.alphaNumeric(16);
  await authorize_seller_join(sellerConnection, {
    body: {
      email: sellerEmail,
      password: sellerPassword,
    },
  });
  // 3. Seller submits approval request
  const approvalRequest =
    await generate_random_shopping_mall_seller_approvals_create(
      sellerConnection,
      { body: {} },
    );
  typia.assert(approvalRequest);
  // 4. Admin approves the seller
  const approvedSeller =
    await api.functional.shoppingMall.admin.sellerApprovals.update(
      adminConnection,
      {
        approvalId: approvalRequest.id,
        body: {
          status: "approved",
          rejection_reason: null,
        } satisfies IShoppingMallSellerApproval.IUpdate,
      },
    );
  typia.assert(approvedSeller);
  // 5. Admin creates a product category
  const category = await generate_random_shopping_mall_admin_categories_create(
    adminConnection,
    { body: {} },
  );
  typia.assert(category);
  // 6. Seller creates a product
  const product = await generate_random_shopping_mall_seller_products_create(
    sellerConnection,
    {
      body: {
        categoryId: category.id,
      },
    },
  );
  typia.assert(product);
  // 7. Seller creates a product variant
  const variant =
    await generate_random_shopping_mall_seller_products_variants_create(
      sellerConnection,
      {
        params: { productId: product.id },
        body: {},
      },
    );
  typia.assert(variant);
  // 8. Seller adds inventory (positive quantity)
  const inventoryRecord =
    await generate_random_shopping_mall_seller_products_variants_inventory_records_create(
      sellerConnection,
      {
        params: { productId: product.id, variantId: variant.id },
        body: {
          quantity: 10,
          note: "Initial stock",
        },
      },
    );
  typia.assert(inventoryRecord);
  // 9. Create customer connection and authenticate
  const customerConnection: api.IConnection = { host: connection.host };
  await authorize_customer_join(customerConnection, {});
  // 10. Customer places an order
  const order = await generate_random_shopping_mall_customer_orders_create(
    customerConnection,
    {
      body: {
        items: [
          {
            product_variant_id: variant.id,
            quantity: 1,
          },
        ],
      },
    },
  );
  typia.assert(order);
  // Extract the order item id
  const orderItem = order.items[0];
  typia.assertGuard(orderItem!);
  // 11. Customer submits a cancellation request
  const cancellationRequest =
    await generate_random_shopping_mall_customer_orders_items_cancellation_requests_create(
      customerConnection,
      {
        params: {
          orderId: order.id,
          orderItemId: orderItem.id,
        },
        body: {
          reason: "I want to cancel this order",
        },
      },
    );
  typia.assert(cancellationRequest);
  // Validate initial state is 'pending'
  TestValidator.equals(
    "initial status is pending",
    cancellationRequest.status,
    "pending",
  );
  // Step A: Seller approves the cancellation request (first call - must succeed)
  const approvedCancellation =
    await api.functional.shoppingMall.seller.cancellationRequests.update(
      sellerConnection,
      {
        cancellationRequestId: cancellationRequest.id,
        body: {
          status: "approved",
        } satisfies IShoppingMallCancellationRequest.IUpdate,
      },
    );
  typia.assert(approvedCancellation);
  TestValidator.equals(
    "status is approved after first call",
    approvedCancellation.status,
    "approved",
  );
  TestValidator.equals(
    "snapshots length is 1 after first call",
    approvedCancellation.snapshots.length,
    1,
  );
  // Step B: Seller tries to respond again (second call - must fail)
  await TestValidator.error(
    "second call must fail - request already resolved",
    async () => {
      await api.functional.shoppingMall.seller.cancellationRequests.update(
        sellerConnection,
        {
          cancellationRequestId: cancellationRequest.id,
          body: {
            status: "rejected",
          } satisfies IShoppingMallCancellationRequest.IUpdate,
        },
      );
    },
  );
  // Validate that the status and snapshots remain unchanged after the failed second attempt
  // The approvedCancellation we got from Step A is the authoritative state
  TestValidator.equals(
    "status remains approved after failed second call",
    approvedCancellation.status,
    "approved",
  );
  TestValidator.equals(
    "snapshots count remains 1 after failed second call",
    approvedCancellation.snapshots.length,
    1,
  );
}

