  // TARGET: Call PATCH snapshots endpoint with empty body - seller has NOT responded
  const snapshotsPage =
    await api.functional.shoppingMall.customer.cancellationRequests.snapshots.index(
      customerConnection,
      {
        cancellationRequestId: cancellationRequest.id,
        body: {} satisfies IShoppingMallCancellationRequestSnapshot.IRequest,
      },
    );
  typia.assert(snapshotsPage);
  // Verify empty data (no seller response yet)
  TestValidator.equals("snapshots data is empty", snapshotsPage.data.length, 0);
  TestValidator.equals(
    "snapshots records is 0",
    snapshotsPage.pagination.records,
    0,
  );
  TestValidator.equals(
    "snapshots pages is 0",
    snapshotsPage.pagination.pages,
    0,
  );
  // Additional filter test: filter by status 'approved' - should also be empty
  const filteredPage =
    await api.functional.shoppingMall.customer.cancellationRequests.snapshots.index(
      customerConnection,
      {
        cancellationRequestId: cancellationRequest.id,
        body: {
          status: "approved",
        } satisfies IShoppingMallCancellationRequestSnapshot.IRequest,
      },
    );
  typia.assert(filteredPage);
  TestValidator.equals(
    "filtered snapshots data is empty",
    filteredPage.data.length,
    0,
  );
  TestValidator.equals(
    "filtered snapshots records is 0",
    filteredPage.pagination.records,
    0,
  );
  TestValidator.equals(
    "filtered snapshots pages is 0",
    filteredPage.pagination.pages,
    0,
  );
}

