      },
    );
  typia.assert(inventoryRecord);
  // -----------------------------------------------------------------------
  // 4. Customer setup: join and place an order
  // -----------------------------------------------------------------------
  const customerConnection: api.IConnection = { host: connection.host };
  await authorize_customer_join(customerConnection, {});
  const order = await generate_random_shopping_mall_customer_orders_create(
    customerConnection,
    {
      body: {
        items: [
          {
            product_variant_id: variant.id,
            quantity: 1,
          },
        ],
      },
    },
  );
  typia.assert(order);
  // Get the first order item
  const orderItem = order.items[0];
  typia.assertGuard(orderItem!);
  // -----------------------------------------------------------------------
  // 5. Customer submits a cancellation request with specific reason text
  // -----------------------------------------------------------------------
  const cancellationReason = "Received wrong item, want to cancel";
  const cancellationRequest =
    await generate_random_shopping_mall_customer_orders_items_cancellation_requests_create(
      customerConnection,
      {
        body: {
          reason: cancellationReason,
        },
        params: {
          orderId: order.id,
          orderItemId: orderItem.id,
        },
      },
    );
  typia.assert(cancellationRequest);
  // -----------------------------------------------------------------------
  // 6. Seller rejects the cancellation request
  // -----------------------------------------------------------------------
  const updatedCancellationRequest =
    await api.functional.shoppingMall.seller.cancellationRequests.update(
      sellerConnection,
      {
        cancellationRequestId: cancellationRequest.id,
        body: {
          status: "rejected",
        } satisfies IShoppingMallCancellationRequest.IUpdate,
      },
    );
  typia.assert(updatedCancellationRequest);
  TestValidator.equals(
    "cancellation request status is rejected",
    updatedCancellationRequest.status,
    "rejected",
  );
  // -----------------------------------------------------------------------
  // 7. Customer lists snapshots to get the snapshotId
  // -----------------------------------------------------------------------
  const snapshotsPage =
    await api.functional.shoppingMall.customer.cancellationRequests.snapshots.index(
      customerConnection,
      {
        cancellationRequestId: cancellationRequest.id,
        body: {} satisfies IShoppingMallCancellationRequestSnapshot.IRequest,
      },
    );
  typia.assert(snapshotsPage);
  TestValidator.predicate(
    "at least one snapshot exists",
    snapshotsPage.data.length > 0,
  );
  const snapshotSummary = snapshotsPage.data[0];
  typia.assertGuard(snapshotSummary!);
  // -----------------------------------------------------------------------
  // 8. Customer fetches the specific snapshot via GET endpoint
  // -----------------------------------------------------------------------
  const snapshot =
    await api.functional.shoppingMall.customer.cancellationRequests.snapshots.at(
      customerConnection,
      {
        cancellationRequestId: cancellationRequest.id,
        snapshotId: snapshotSummary.id,
      },
    );
  typia.assert(snapshot);
  // -----------------------------------------------------------------------
  // Validations
  // -----------------------------------------------------------------------
  // Status is 'rejected'
  TestValidator.equals(
    "snapshot status is rejected",
    snapshot.status,
    "rejected",
  );
  // The verbatim reason text from the customer is preserved
  TestValidator.equals(
    "snapshot reason matches original cancellation reason",
    snapshot.reason,
    cancellationReason,
  );
  // cancellation_request_id matches the parent cancellation request
  TestValidator.equals(
    "snapshot cancellation_request_id matches",
    snapshot.cancellation_request_id,
    cancellationRequest.id,
  );
  // -----------------------------------------------------------------------
  // 9. Verify immutability: calling GET again returns the exact same record
  // -----------------------------------------------------------------------
  const snapshotAgain =
    await api.functional.shoppingMall.customer.cancellationRequests.snapshots.at(
      customerConnection,
      {
        cancellationRequestId: cancellationRequest.id,
        snapshotId: snapshotSummary.id,
      },
    );
  typia.assert(snapshotAgain);
  TestValidator.equals(
    "snapshot is immutable - id",
    snapshot.id,
    snapshotAgain.id,
  );
  TestValidator.equals(
    "snapshot is immutable - status",
    snapshot.status,
    snapshotAgain.status,
  );
  TestValidator.equals(
    "snapshot is immutable - reason",
    snapshot.reason,
    snapshotAgain.reason,
  );
  TestValidator.equals(
    "snapshot is immutable - cancellation_request_id",
    snapshot.cancellation_request_id,
    snapshotAgain.cancellation_request_id,
  );
  TestValidator.equals(
    "snapshot is immutable - created_at",
    snapshot.created_at,
    snapshotAgain.created_at,
  );
}

