      },
    );
  typia.assert(approvedApproval);
  // 6. Seller creates a product
  const product = await generate_random_shopping_mall_seller_products_create(
    sellerConnection,
    { body: { categoryId: category.id } },
  );
  typia.assert(product);
  // 7. Seller creates a variant
  const variant =
    await generate_random_shopping_mall_seller_products_variants_create(
      sellerConnection,
      {
        params: { productId: product.id },
        body: {},
      },
    );
  typia.assert(variant);
  // 8. Seller adds inventory stock
  const inventoryRecord =
    await generate_random_shopping_mall_seller_products_variants_inventory_records_create(
      sellerConnection,
      {
        params: { productId: product.id, variantId: variant.id },
        body: { quantity: 10, note: "Initial stock" },
      },
    );
  typia.assert(inventoryRecord);
  // 9. Customer registers
  const customerConnection: api.IConnection = { host: connection.host };
  await authorize_customer_join(customerConnection, {});
  // 10. Customer places an order (order item status becomes 'paid', NOT 'delivered')
  const order = await generate_random_shopping_mall_customer_orders_create(
    customerConnection,
    {
      body: {
        items: [
          {
            product_variant_id: variant.id,
            quantity: 1,
          },
        ],
      },
    },
  );
  typia.assert(order);
  // Get the first order item (which is in 'paid' status)
  const orderItem = order.items[0];
  if (!orderItem)
    throw new Error("Expected at least one order item in the created order");
  // Validate that the order item is in 'paid' status (prerequisite for this test)
  TestValidator.equals("order item status is paid", orderItem.status, "paid");
  // 11. Primary test: Attempt to submit a refund request for the 'paid' order item.
  // Business rule: refund requests are only permitted for 'delivered' items.
  // Expecting an error (HTTP 422 — item not in 'delivered' status).
  await TestValidator.error(
    "refund request rejected for non-delivered (paid) item",
    async () => {
      await api.functional.shoppingMall.customer.orders.items.refundRequests.create(
        customerConnection,
        {
          orderId: order.id,
          orderItemId: orderItem.id,
          body: {
            reason: "Changed my mind",
          } satisfies IShoppingMallRefundRequest.ICreate,
        },
      );
    },
  );
}

