export async function test_api_refund_request_duplicate_submission_rejected(
  connection: api.IConnection,
): Promise<void> {
  // =========================================================
  // 1. Admin setup
  // =========================================================
  const adminConnection: api.IConnection = { host: connection.host };
  await authorize_admin_join(adminConnection, {});
  // Admin creates a category
  const category = await generate_random_shopping_mall_admin_categories_create(
    adminConnection,
    { body: { name: RandomGenerator.alphabets(8) } },
  );
  typia.assert(category);
  // =========================================================
  // 2. Seller setup
  // =========================================================
  const sellerPassword = RandomGenerator.alphaNumeric(16);
  const sellerEmail = typia.random<string & tags.Format<"email">>();
  const sellerConnection: api.IConnection = { host: connection.host };
  await authorize_seller_join(sellerConnection, {
    body: {
      email: sellerEmail,
      password: sellerPassword,
      shop_name: RandomGenerator.name(),
      href: typia.random<string & tags.Format<"uri">>(),
      referrer: typia.random<string & tags.Format<"uri">>(),
    },
  });
  // Seller submits approval request
  const approval = await generate_random_shopping_mall_seller_approvals_create(
    sellerConnection,
    { body: {} },
  );
  typia.assert(approval);
  // Admin approves the seller
  const approvedApproval =
    await api.functional.shoppingMall.admin.sellerApprovals.update(
      adminConnection,
      {
        approvalId: approval.id,
        body: {
          status: "approved",
          rejection_reason: null,
        } satisfies IShoppingMallSellerApproval.IUpdate,
      },
    );
  typia.assert(approvedApproval);
  TestValidator.equals(
    "seller approval status",
    approvedApproval.status,
    "approved",
  );
  // Seller creates a product
  const product = await generate_random_shopping_mall_seller_products_create(
    sellerConnection,
    {
      body: {
        name: RandomGenerator.paragraph({ sentences: 2 }),
        description: RandomGenerator.paragraph({ sentences: 3 }),
        base_price: 10000,
        categoryId: category.id,
      },
    },
  );
  typia.assert(product);
  // Seller creates a product variant
  const variant =
    await generate_random_shopping_mall_seller_products_variants_create(
      sellerConnection,
      {
        params: { productId: product.id },
        body: {
          sku: `SKU-${RandomGenerator.alphaNumeric(10)}`,
          priceOverride: null,
          options: [
            {
              id: typia.random<string & tags.Format<"uuid">>(),
              product_variant_id: typia.random<string & tags.Format<"uuid">>(),
              key: "color",
              value: "blue",
              sequence: 0,
              created_at: new Date().toISOString(),
            },
          ],
        },
      },
    );
  typia.assert(variant);
  // Seller adds inventory stock
  const inventoryRecord =
    await generate_random_shopping_mall_seller_products_variants_inventory_records_create(
      sellerConnection,
      {
        params: { productId: product.id, variantId: variant.id },
        body: {
          quantity: 100,
          note: "Initial stock for refund duplicate test",
        },
      },
    );
  typia.assert(inventoryRecord);
  // =========================================================
  // 3. Customer setup
  // =========================================================
  const customerConnection: api.IConnection = { host: connection.host };
  await authorize_customer_join(customerConnection, {});
  // Customer places an order
  const order = await generate_random_shopping_mall_customer_orders_create(
    customerConnection,
    {
      body: {
        recipient_name: RandomGenerator.name(),
        recipient_phone: RandomGenerator.mobile(),
        shipping_address_line1: "123 Test Street",
        shipping_address_line2: null,
        shipping_city: "Seoul",
        shipping_state: null,
        shipping_postal_code: "12345",
        shipping_country: "KR",
        items: [
          {
            product_variant_id: variant.id,
            quantity: 1,
          },
        ],
      },
    },
  );
  typia.assert(order);
  // Extract order item
  const orderItem = order.items[0];
  typia.assertGuard(orderItem!);
  const orderId = order.id;
  const orderItemId = orderItem.id;
  // =========================================================
  // 4. Seller creates a shipment (transitions order item to 'shipped')
  // =========================================================
  const shipment =
    await generate_random_shopping_mall_seller_orders_shipments_create(
      sellerConnection,
      {
        params: { orderId },
        body: {
          carrier: "TestCarrier",
          trackingNumber: `TRK-${RandomGenerator.alphaNumeric(10)}`,
          orderItemIds: [orderItemId],
          shippedAt: new Date().toISOString(),
          estimatedDeliveryAt: new Date().toISOString(),
        },
      },
    );
  typia.assert(shipment);
  // =========================================================
  // 5. Submit FIRST refund request (should succeed once item is delivered)
  // =========================================================
  const firstRefundRequest =
    await generate_random_shopping_mall_customer_orders_items_refund_requests_create(
      customerConnection,
      {
        params: { orderId, orderItemId },
        body: {
          reason: "First refund request - product defective",
        },
      },
    );
  typia.assert(firstRefundRequest);
  TestValidator.equals(
    "first refund request status is pending",
    firstRefundRequest.status,
    "pending",
  );
  // =========================================================
  // 6. PRIMARY TEST: Submit SECOND refund request → must be rejected (409)
  // =========================================================
  await TestValidator.error(
    "duplicate refund request submission must be rejected",
    async () => {
      await generate_random_shopping_mall_customer_orders_items_refund_requests_create(
        customerConnection,
        {
          params: { orderId, orderItemId },
          body: {
            reason: "Second refund request attempt",
          },
        },
      );
    },
  );
  // =========================================================
  // 7. Verify original refund request remains unchanged
  // =========================================================
  TestValidator.equals(
    "first refund request id is preserved",
    typeof firstRefundRequest.id,
    "string",
  );
  TestValidator.equals(
    "first refund request status remains pending",
    firstRefundRequest.status,
    "pending",
  );
}

