export async function test_api_refund_request_snapshots_pagination_and_sorting(
  connection: api.IConnection,
): Promise<void> {
  // ─── 1. Admin setup ───────────────────────────────────────────────
  const adminConnection: api.IConnection = { host: connection.host };
  await authorize_admin_join(adminConnection, {
    body: {
      email: typia.random<string & tags.Format<"email">>(),
      password: typia.random<string & tags.Format<"password">>(),
    },
  });
  // 2. Admin creates a category
  const category = await generate_random_shopping_mall_admin_categories_create(
    adminConnection,
    { body: { name: RandomGenerator.alphabets(8) } },
  );
  typia.assert(category);
  // ─── 3. Seller setup ──────────────────────────────────────────────
  const sellerConnection: api.IConnection = { host: connection.host };
  await authorize_seller_join(sellerConnection, {
    body: {
      email: typia.random<string & tags.Format<"email">>(),
      password: RandomGenerator.alphaNumeric(16),
      shop_name: RandomGenerator.name(),
      href: typia.random<string & tags.Format<"uri">>(),
      referrer: typia.random<string & tags.Format<"uri">>(),
    },
  });
  // 4. Seller submits approval
  const approval = await generate_random_shopping_mall_seller_approvals_create(
    sellerConnection,
    { body: {} },
  );
  typia.assert(approval);
  // 5. Admin approves the seller
  const approvedApproval =
    await api.functional.shoppingMall.admin.sellerApprovals.update(
      adminConnection,
      {
        approvalId: approval.id,
        body: {
          status: "approved",
          rejection_reason: null,
        } satisfies IShoppingMallSellerApproval.IUpdate,
      },
    );
  typia.assert(approvedApproval);
  // 6. Seller creates a product
  const product = await generate_random_shopping_mall_seller_products_create(
    sellerConnection,
    {
      body: {
        name: RandomGenerator.paragraph({ sentences: 2 }),
        description: RandomGenerator.paragraph({ sentences: 3 }),
        base_price: 10000,
        categoryId: category.id,
      },
    },
  );
  typia.assert(product);
  // 7. Seller creates a variant
  const variant =
    await generate_random_shopping_mall_seller_products_variants_create(
      sellerConnection,
      {
        body: {
          sku: RandomGenerator.alphaNumeric(16),
          priceOverride: null,
          options: [
            {
              id: typia.random<string & tags.Format<"uuid">>(),
              product_variant_id: typia.random<string & tags.Format<"uuid">>(),
              key: "color",
              value: "red",
              sequence: 0,
              created_at: new Date().toISOString(),
            },
          ],
        },
        params: { productId: product.id },
      },
    );
  typia.assert(variant);
  // 8. Seller adds inventory
  const inventoryRecord =
    await generate_random_shopping_mall_seller_products_variants_inventory_records_create(
      sellerConnection,
      {
        body: { quantity: 100, note: "Initial stock" },
        params: { productId: product.id, variantId: variant.id },
      },
    );
  typia.assert(inventoryRecord);
  // ─── 9. Customer setup ────────────────────────────────────────────
  const customerConnection: api.IConnection = { host: connection.host };
  await authorize_customer_join(customerConnection, {
    body: {
      email: typia.random<string & tags.Format<"email">>(),
      password: RandomGenerator.alphaNumeric(16),
      nickname: RandomGenerator.name(),
      href: typia.random<string & tags.Format<"uri">>(),
      referrer: typia.random<string & tags.Format<"uri">>(),
    },
  });
  // 10. Customer places an order
  const order = await generate_random_shopping_mall_customer_orders_create(
    customerConnection,
    {
      body: {
        recipient_name: RandomGenerator.name(),
        recipient_phone: RandomGenerator.mobile(),
        shipping_address_line1: "123 Test Street",
        shipping_city: "Test City",
        shipping_postal_code: "12345",
        shipping_country: "US",
        items: [{ product_variant_id: variant.id, quantity: 1 }],
      },
    },
  );
  typia.assert(order);
  const orderItem = order.items[0]!;
  // 11. Seller creates a shipment and assigns the order item
  const shipment =
    await generate_random_shopping_mall_seller_orders_shipments_create(
      sellerConnection,
      {
        body: {
          carrier: "FedEx",
          trackingNumber: RandomGenerator.alphaNumeric(12),
          orderItemIds: [orderItem.id],
        },
        params: { orderId: order.id },
      },
    );
  typia.assert(shipment);
  // 12. Seller updates the shipment to mark delivery
  const updatedShipment =
    await api.functional.shoppingMall.seller.orders.shipments.update(
      sellerConnection,
      {
        orderId: order.id,
        shipmentId: shipment.id,
        body: {
          carrier: "FedEx",
          tracking_number: RandomGenerator.alphaNumeric(12),
          shipped_at: new Date().toISOString(),
          estimated_delivery_at: new Date().toISOString(),
        } satisfies IShoppingMallShipment.IUpdate,
      },
    );
  typia.assert(updatedShipment);
  // 13. Customer submits a refund request
  const refundRequest =
    await generate_random_shopping_mall_customer_orders_items_refund_requests_create(
      customerConnection,
      {
        body: { reason: "Product was damaged on arrival" },
        params: { orderId: order.id, orderItemId: orderItem.id },
      },
    );
  typia.assert(refundRequest);
  // 14. Seller responds to the refund request (creates a snapshot)
  const respondedRefundRequest =
    await api.functional.shoppingMall.seller.refundRequests.update(
      sellerConnection,
      {
        refundRequestId: refundRequest.id,
        body: {
          status: "rejected",
          note: "Unable to process refund at this time.",
        } satisfies IShoppingMallRefundRequest.IUpdate,
      },
    );
  typia.assert(respondedRefundRequest);
  // ─── Test A: Explicit Pagination ──────────────────────────────────
  const pageA =
    await api.functional.shoppingMall.customer.refundRequests.snapshots.index(
      customerConnection,
      {
        refundRequestId: refundRequest.id,
        body: {
          page: 1,
          limit: 5,
        } satisfies IShoppingMallRefundRequestSnapshot.IRequest,
      },
    );
  typia.assert(pageA);
  TestValidator.equals(
    "pagination.current equals 1",
    pageA.pagination.current,
    1,
  );
  TestValidator.equals("pagination.limit equals 5", pageA.pagination.limit, 5);
  TestValidator.equals(
    "pagination.records equals 1",
    pageA.pagination.records,
    1,
  );
  TestValidator.equals("data has 1 element", pageA.data.length, 1);
  // ─── Test B: Descending Sort ──────────────────────────────────────
  const pageB =
    await api.functional.shoppingMall.customer.refundRequests.snapshots.index(
      customerConnection,
      {
        refundRequestId: refundRequest.id,
        body: {
          sort: "desc",
        } satisfies IShoppingMallRefundRequestSnapshot.IRequest,
      },
    );
  typia.assert(pageB);
  TestValidator.equals("desc sort returns 1 snapshot", pageB.data.length, 1);
  TestValidator.predicate(
    "snapshot createdAt is valid ISO 8601",
    () => !isNaN(Date.parse(pageB.data[0]!.createdAt)),
  );
  // ─── Test C: Future Date Filter ───────────────────────────────────
  const futureDate = new Date(
    Date.now() + 1000 * 60 * 60 * 24 * 30,
  ).toISOString();
  const pageC =
    await api.functional.shoppingMall.customer.refundRequests.snapshots.index(
      customerConnection,
      {
        refundRequestId: refundRequest.id,
        body: {
          from: futureDate,
        } satisfies IShoppingMallRefundRequestSnapshot.IRequest,
      },
    );
  typia.assert(pageC);
  TestValidator.equals(
    "future filter returns empty data",
    pageC.data.length,
    0,
  );
  TestValidator.equals(
    "future filter pagination.records is 0",
    pageC.pagination.records,
    0,
  );
}

