export async function test_api_refund_request_snapshot_customer_view_after_seller_approval(
  connection: api.IConnection,
): Promise<void> {
  // 1. Admin setup
  const adminConnection: api.IConnection = { host: connection.host };
  await authorize_admin_join(adminConnection, {});
  // 2. Admin creates a product category
  const category = await generate_random_shopping_mall_admin_categories_create(
    adminConnection,
    {
      body: { name: RandomGenerator.alphabets(8) },
    },
  );
  typia.assert(category);
  // 3. Seller setup
  const sellerPassword = RandomGenerator.alphaNumeric(16);
  const sellerConnection: api.IConnection = { host: connection.host };
  await authorize_seller_join(sellerConnection, {
    body: {
      email: typia.random<string & tags.Format<"email">>(),
      password: sellerPassword,
      shop_name: RandomGenerator.name(),
      href: typia.random<string & tags.Format<"uri">>(),
      referrer: typia.random<string & tags.Format<"uri">>(),
    },
  });
  // 4. Seller submits an approval request
  const approval = await generate_random_shopping_mall_seller_approvals_create(
    sellerConnection,
    {},
  );
  typia.assert(approval);
  // 5. Admin approves the seller
  const approvedSeller =
    await api.functional.shoppingMall.admin.sellerApprovals.update(
      adminConnection,
      {
        approvalId: approval.id,
        body: {
          status: "approved",
          rejection_reason: null,
        } satisfies IShoppingMallSellerApproval.IUpdate,
      },
    );
  typia.assert(approvedSeller);
  // 6. Seller creates a product
  const product = await generate_random_shopping_mall_seller_products_create(
    sellerConnection,
    {
      body: {
        categoryId: category.id,
        name: RandomGenerator.name(),
        description: RandomGenerator.paragraph({ sentences: 3 }),
        base_price: 10000,
      },
    },
  );
  typia.assert(product);
  // 7. Seller creates a product variant with a unique SKU
  const variant =
    await generate_random_shopping_mall_seller_products_variants_create(
      sellerConnection,
      {
        params: { productId: product.id },
        body: {
          sku: `SKU-${RandomGenerator.alphaNumeric(12)}`,
          options: [{ key: "color", value: "red", sequence: 0 }],
        },
      },
    );
  typia.assert(variant);
  // 8. Seller adds inventory (100 units)
  const inventoryRecord =
    await generate_random_shopping_mall_seller_products_variants_inventory_records_create(
      sellerConnection,
      {
        params: { productId: product.id, variantId: variant.id },
        body: {
          quantity: 100,
          note: "Initial stock",
        },
      },
    );
  typia.assert(inventoryRecord);
  // 9. Customer setup
  const customerConnection: api.IConnection = { host: connection.host };
  await authorize_customer_join(customerConnection, {
    body: {
      email: typia.random<string & tags.Format<"email">>(),
      password: RandomGenerator.alphaNumeric(16),
      nickname: RandomGenerator.name(),
      href: typia.random<string & tags.Format<"uri">>(),
      referrer: typia.random<string & tags.Format<"uri">>(),
    },
  });
  // 10. Customer places an order
  const order = await generate_random_shopping_mall_customer_orders_create(
    customerConnection,
    {
      body: {
        recipient_name: RandomGenerator.name(),
        recipient_phone: RandomGenerator.mobile(),
        shipping_address_line1: "123 Main St",
        shipping_city: "Seoul",
        shipping_postal_code: "12345",
        shipping_country: "KR",
        items: [
          {
            product_variant_id: variant.id,
            quantity: 1,
          },
        ],
      },
    },
  );
  typia.assert(order);
  const orderItem = order.items[0]!;
  // 11. Seller creates a shipment for the order (includes assigning the order item)
  const shipment =
    await generate_random_shopping_mall_seller_orders_shipments_create(
      sellerConnection,
      {
        params: { orderId: order.id },
        body: {
          carrier: "FedEx",
          trackingNumber: `TRACK-${RandomGenerator.alphaNumeric(10)}`,
          orderItemIds: [orderItem.id],
          shippedAt: new Date().toISOString(),
        },
      },
    );
  typia.assert(shipment);
  // 13. Seller updates the shipment with shipped details to advance status
  const updatedShipment =
    await api.functional.shoppingMall.seller.orders.shipments.update(
      sellerConnection,
      {
        orderId: order.id,
        shipmentId: shipment.id,
        body: {
          carrier: "FedEx",
          shipped_at: new Date().toISOString(),
          estimated_delivery_at: new Date().toISOString(),
        } satisfies IShoppingMallShipment.IUpdate,
      },
    );
  typia.assert(updatedShipment);
  // 14. Customer submits a refund request with a specific reason
  const refundReason = "Product was defective";
  const refundRequest =
    await generate_random_shopping_mall_customer_orders_items_refund_requests_create(
      customerConnection,
      {
        params: { orderId: order.id, orderItemId: orderItem.id },
        body: { reason: refundReason },
      },
    );
  typia.assert(refundRequest);
  // 15. Seller approves the refund request (triggers automatic snapshot creation)
  const updatedRefundRequest =
    await api.functional.shoppingMall.seller.refundRequests.update(
      sellerConnection,
      {
        refundRequestId: refundRequest.id,
        body: {
          status: "approved",
          note: "Refund approved",
        } satisfies IShoppingMallRefundRequest.IUpdate,
      },
    );
  typia.assert(updatedRefundRequest);
  // Discover snapshotId via PATCH /customer/refundRequests/{refundRequestId}/snapshots
  const snapshotList =
    await api.functional.shoppingMall.customer.refundRequests.snapshots.index(
      customerConnection,
      {
        refundRequestId: refundRequest.id,
        body: {} satisfies IShoppingMallRefundRequestSnapshot.IRequest,
      },
    );
  typia.assert(snapshotList);
  TestValidator.predicate(
    "should have at least one snapshot",
    snapshotList.data.length > 0,
  );
  const snapshotSummary = snapshotList.data[0]!;
  TestValidator.equals(
    "snapshot refundRequestId matches",
    snapshotSummary.refundRequestId,
    refundRequest.id,
  );
  // Call GET /customer/refundRequests/{refundRequestId}/snapshots/{snapshotId}
  const snapshot =
    await api.functional.shoppingMall.customer.refundRequests.snapshots.at(
      customerConnection,
      {
        refundRequestId: refundRequest.id,
        snapshotId: snapshotSummary.id,
      },
    );
  typia.assert(snapshot);
  // Validate snapshot fields
  TestValidator.equals("snapshot id matches", snapshot.id, snapshotSummary.id);
  TestValidator.equals(
    "refund request id in snapshot matches",
    snapshot.refundRequest.id,
    refundRequest.id,
  );
  TestValidator.equals(
    "refund request status is approved",
    snapshot.refundRequest.status,
    "approved",
  );
  TestValidator.equals(
    "reason is verbatim customer input",
    snapshot.refundRequest.reason,
    refundReason,
  );
  TestValidator.equals(
    "orderItemId references correct order item",
    snapshot.refundRequest.orderItemId,
    orderItem.id,
  );
  // Immutability check: call the endpoint again and compare
  const snapshot2 =
    await api.functional.shoppingMall.customer.refundRequests.snapshots.at(
      customerConnection,
      {
        refundRequestId: refundRequest.id,
        snapshotId: snapshotSummary.id,
      },
    );
  typia.assert(snapshot2);
  TestValidator.equals("snapshot is immutable - id", snapshot.id, snapshot2.id);
  TestValidator.equals(
    "snapshot is immutable - created_at",
    snapshot.created_at,
    snapshot2.created_at,
  );
  TestValidator.equals(
    "snapshot is immutable - refundRequest.id",
    snapshot.refundRequest.id,
    snapshot2.refundRequest.id,
  );
  TestValidator.equals(
    "snapshot is immutable - refundRequest.reason",
    snapshot.refundRequest.reason,
    snapshot2.refundRequest.reason,
  );
  TestValidator.equals(
    "snapshot is immutable - refundRequest.status",
    snapshot.refundRequest.status,
    snapshot2.refundRequest.status,
  );
}

