  const orderItem = order.items[0]!;
  // Test 1: Attempt to review 'paid' item — must be rejected (422)
  await TestValidator.error("review rejected for paid item", async () => {
    await api.functional.shoppingMall.customer.products.reviews.create(
      customerConnection,
      {
        productId: product.id,
        body: {
          order_item_id: orderItem.id,
          rating: 5,
          body: "Great product!",
        } satisfies IShoppingMallReview.ICreate,
      },
    );
  });
  // 11. Seller creates a shipment and assigns the order item
  //     (this transitions the order item from 'paid' to 'shipped')
  const shipment =
    await generate_random_shopping_mall_seller_orders_shipments_create(
      sellerConnection,
      {
        params: { orderId: order.id },
        body: {
          orderItemIds: [orderItem.id],
        },
      },
    );
  typia.assert(shipment);
  // Test 2: Attempt to review 'shipped' item — must also be rejected (422)
  await TestValidator.error("review rejected for shipped item", async () => {
    await api.functional.shoppingMall.customer.products.reviews.create(
      customerConnection,
      {
        productId: product.id,
        body: {
          order_item_id: orderItem.id,
          rating: 5,
          body: "Shipped but not delivered yet.",
        } satisfies IShoppingMallReview.ICreate,
      },
    );
  });
}

