export async function test_api_review_deletion_other_customer_forbidden(
  connection: api.IConnection,
): Promise<void> {
  // =========================================================================
  // Step 1: Admin Setup - Join and create a product category
  // =========================================================================
  const adminConnection: api.IConnection = { host: connection.host };
  await authorize_admin_join(adminConnection, {});
  const category = await generate_random_shopping_mall_admin_categories_create(
    adminConnection,
    { body: { name: RandomGenerator.alphabets(8) } },
  );
  typia.assert(category);
  // =========================================================================
  // Step 2: Seller Setup - Join, submit approval, get approved, create product
  // =========================================================================
  const sellerEmail = typia.random<string & tags.Format<"email">>();
  const sellerPassword = typia.random<string & tags.Format<"password">>();
  const sellerConnection: api.IConnection = { host: connection.host };
  await authorize_seller_join(sellerConnection, {
    body: {
      email: sellerEmail,
      password: sellerPassword,
    },
  });
  const approval = await generate_random_shopping_mall_seller_approvals_create(
    sellerConnection,
    {},
  );
  typia.assert(approval);
  const approvedApproval =
    await api.functional.shoppingMall.admin.sellerApprovals.update(
      adminConnection,
      {
        approvalId: approval.id,
        body: {
          status: "approved",
          rejection_reason: null,
        } satisfies IShoppingMallSellerApproval.IUpdate,
      },
    );
  typia.assert(approvedApproval);
  await authorize_seller_login(sellerConnection, {
    body: {
      email: sellerEmail,
      password: sellerPassword,
    } satisfies IShoppingMallSeller.ILogin,
  });
  const product = await generate_random_shopping_mall_seller_products_create(
    sellerConnection,
    {
      body: {
        name: RandomGenerator.paragraph({ sentences: 2 }),
        description: RandomGenerator.paragraph({ sentences: 3 }),
        base_price: 10000,
        categoryId: category.id,
      },
    },
  );
  typia.assert(product);
  const variantOption = typia.random<IShoppingMallProductVariantOption>();
  const variant =
    await generate_random_shopping_mall_seller_products_variants_create(
      sellerConnection,
      {
        params: { productId: product.id },
        body: {
          sku: `SKU-${RandomGenerator.alphaNumeric(10)}`,
          options: [
            { ...variantOption, key: "color", value: "red", sequence: 0 },
          ],
        },
      },
    );
  typia.assert(variant);
  const inventoryRecord =
    await generate_random_shopping_mall_seller_products_variants_inventory_records_create(
      sellerConnection,
      {
        params: { productId: product.id, variantId: variant.id },
        body: {
          quantity: 100,
          note: "Initial stock",
        },
      },
    );
  typia.assert(inventoryRecord);
  // =========================================================================
  // Step 3: Customer A - Join, place order, fulfill through shipment, write review
  // =========================================================================
  const customerAConnection: api.IConnection = { host: connection.host };
  await authorize_customer_join(customerAConnection, {
    body: {
      email: typia.random<string & tags.Format<"email">>(),
      password: typia.random<string & tags.MinLength<8> & tags.Format<"password">>() satisfies string as string & tags.MinLength<8> & tags.Format<"password">,
      nickname: RandomGenerator.name(),
    },
  });
  const order = await generate_random_shopping_mall_customer_orders_create(
    customerAConnection,
    {
      body: {
        recipient_name: RandomGenerator.name(),
        recipient_phone: RandomGenerator.mobile(),
        shipping_address_line1: "123 Main Street",
        shipping_city: "Seoul",
        shipping_postal_code: "12345",
        shipping_country: "KR",
        items: [
          {
            product_variant_id: variant.id,
            quantity: 1,
          },
        ],
      },
    },
  );
  typia.assert(order);
  const orderItemId = order.items[0]!.id;
  const shipment =
    await generate_random_shopping_mall_seller_orders_shipments_create(
      sellerConnection,
      {
        params: { orderId: order.id },
        body: {
          carrier: "FedEx",
          trackingNumber: `TRACK-${RandomGenerator.alphaNumeric(10)}`,
          orderItemIds: [orderItemId],
          shippedAt: new Date().toISOString(),
          estimatedDeliveryAt: new Date().toISOString(),
        },
      },
    );
  typia.assert(shipment);
  const updatedShipment =
    await api.functional.shoppingMall.seller.orders.shipments.update(
      sellerConnection,
      {
        orderId: order.id,
        shipmentId: shipment.id,
        body: {
          carrier: "FedEx",
          tracking_number: shipment.tracking_number,
          shipped_at: new Date().toISOString(),
          estimated_delivery_at: new Date().toISOString(),
        } satisfies IShoppingMallShipment.IUpdate,
      },
    );
  typia.assert(updatedShipment);
  const review =
    await generate_random_shopping_mall_customer_products_reviews_create(
      customerAConnection,
      {
        params: { productId: product.id },
        body: {
          order_item_id: orderItemId,
          rating: 5,
          body: "Great product! Highly recommended.",
        },
      },
    );
  typia.assert(review);
  // =========================================================================
  // Step 4: Customer B - Join as a completely independent, separate customer
  // =========================================================================
  const customerBConnection: api.IConnection = { host: connection.host };
  await authorize_customer_join(customerBConnection, {
    body: {
      email: typia.random<string & tags.Format<"email">>(),
      password: typia.random<string & tags.MinLength<8> & tags.Format<"password">>() satisfies string as string & tags.MinLength<8> & tags.Format<"password">,
      nickname: RandomGenerator.name(),
    },
  });
  // =========================================================================
  // Step 5: Test - Customer B tries to delete Customer A's review → must get 403
  // =========================================================================
  await TestValidator.httpError(
    "Customer B cannot delete Customer A's review - must get 403 Forbidden",
    403,
    async () => {
      await api.functional.shoppingMall.customer.products.reviews.erase(
        customerBConnection,
        {
          productId: product.id,
          reviewId: review.id,
        },
      );
    },
  );
  // =========================================================================
  // Step 6: Confirm review still exists - Customer A can delete their own review
  // =========================================================================
  await api.functional.shoppingMall.customer.products.reviews.erase(
    customerAConnection,
    {
      productId: product.id,
      reviewId: review.id,
    },
  );
}

