export async function test_api_review_snapshot_access_denied_for_other_customer(
  connection: api.IConnection,
): Promise<void> {
  // Step 1: Register admin
  const adminConnection: api.IConnection = { host: connection.host };
  await authorize_admin_join(adminConnection, {});
  // Step 2: Admin creates a product category
  const category = await generate_random_shopping_mall_admin_categories_create(
    adminConnection,
    { body: {} },
  );
  typia.assert(category);
  // Step 3: Register seller
  const sellerEmail = typia.random<string & tags.Format<"email">>();
  const sellerPassword = RandomGenerator.alphaNumeric(16);
  const sellerConnection: api.IConnection = { host: connection.host };
  await authorize_seller_join(sellerConnection, {
    body: {
      email: sellerEmail,
      password: sellerPassword,
      shop_name: RandomGenerator.name(),
      href: typia.random<string & tags.Format<"uri">>(),
      referrer: typia.random<string & tags.Format<"uri">>(),
    },
  });
  // Step 4: Seller submits approval request
  const approval = await generate_random_shopping_mall_seller_approvals_create(
    sellerConnection,
    { body: {} },
  );
  typia.assert(approval);
  // Step 5: Admin approves the seller
  const approvedApproval =
    await api.functional.shoppingMall.admin.sellerApprovals.update(
      adminConnection,
      {
        approvalId: approval.id,
        body: {
          status: "approved",
          rejection_reason: null,
        } satisfies IShoppingMallSellerApproval.IUpdate,
      },
    );
  typia.assert(approvedApproval);
  // Step 6: Seller creates a product
  const product = await generate_random_shopping_mall_seller_products_create(
    sellerConnection,
    {
      body: {
        categoryId: category.id,
      },
    },
  );
  typia.assert(product);
  // Step 7: Seller creates a product variant
  const variant =
    await generate_random_shopping_mall_seller_products_variants_create(
      sellerConnection,
      {
        params: { productId: product.id },
        body: {},
      },
    );
  typia.assert(variant);
  // Step 8: Seller creates inventory record (quantity = 10)
  const inventoryRecord =
    await generate_random_shopping_mall_seller_products_variants_inventory_records_create(
      sellerConnection,
      {
        params: { productId: product.id, variantId: variant.id },
        body: { quantity: 10, note: "Initial stock for testing" },
      },
    );
  typia.assert(inventoryRecord);
  // Step 9: Register Customer A (the review author)
  const customerAEmail = typia.random<string & tags.Format<"email">>();
  const customerAPassword = RandomGenerator.alphaNumeric(16);
  const customerAConnection: api.IConnection = { host: connection.host };
  await authorize_customer_join(customerAConnection, {
    body: {
      email: customerAEmail,
      password: customerAPassword,
      nickname: RandomGenerator.name(1),
      href: typia.random<string & tags.Format<"uri">>(),
      referrer: typia.random<string & tags.Format<"uri">>(),
    },
  });
  // Step 10: Customer A places an order
  const order = await generate_random_shopping_mall_customer_orders_create(
    customerAConnection,
    {
      body: {
        recipient_name: RandomGenerator.name(),
        recipient_phone: RandomGenerator.mobile(),
        shipping_address_line1: "123 Test Street",
        shipping_city: "Test City",
        shipping_postal_code: "12345",
        shipping_country: "US",
        items: [
          {
            product_variant_id: variant.id,
            quantity: 1,
          },
        ],
      },
    },
  );
  typia.assert(order);
  // Get the order item id from the order
  const orderItem = order.items[0];
  TestValidator.predicate("order item exists", orderItem !== undefined);
  // Step 11: Customer A submits a review (assumes order item is in delivered status)
  const review =
    await generate_random_shopping_mall_customer_products_reviews_create(
      customerAConnection,
      {
        params: { productId: product.id },
        body: {
          order_item_id: orderItem!.id,
          rating: 5,
          body: "Excellent product!",
        },
      },
    );
  typia.assert(review);
  // Step 12: Register Customer B (the unauthorized accessor)
  const customerBEmail = typia.random<string & tags.Format<"email">>();
  const customerBPassword = RandomGenerator.alphaNumeric(16);
  const customerBConnection: api.IConnection = { host: connection.host };
  await authorize_customer_join(customerBConnection, {
    body: {
      email: customerBEmail,
      password: customerBPassword,
      nickname: RandomGenerator.name(1),
      href: typia.random<string & tags.Format<"uri">>(),
      referrer: typia.random<string & tags.Format<"uri">>(),
    },
  });
  // Test: Customer B attempts to access Customer A's review snapshots -> should get 403
  await TestValidator.httpError(
    "Customer B cannot access Customer A's review snapshots",
    403,
    async () => {
      await api.functional.shoppingMall.customer.products.reviews.snapshots.index(
        customerBConnection,
        {
          productId: product.id,
          reviewId: review.id,
          body: {} satisfies IShoppingMallReviewSnapshot.IRequest,
        },
      );
    },
  );
  // Verify: Customer A (the actual author) CAN access their own review snapshots
  const snapshots =
    await api.functional.shoppingMall.customer.products.reviews.snapshots.index(
      customerAConnection,
      {
        productId: product.id,
        reviewId: review.id,
        body: {} satisfies IShoppingMallReviewSnapshot.IRequest,
      },
    );
  typia.assert(snapshots);
  TestValidator.predicate(
    "Customer A's snapshot list has at least one snapshot",
    snapshots.data.length >= 1,
  );
}

