export async function test_api_review_snapshot_access_denied_for_other_customer(
  connection: api.IConnection,
): Promise<void> {
  // ─── 1. Admin joins ───────────────────────────────────────────────────────
  const adminConnection: api.IConnection = { host: connection.host };
  await authorize_admin_join(adminConnection, {});
  // ─── 2. Create category (as admin) ────────────────────────────────────────
  const category = await generate_random_shopping_mall_admin_categories_create(
    adminConnection,
    {},
  );
  typia.assert(category);
  // ─── 3. Seller joins ──────────────────────────────────────────────────────
  const sellerConnection: api.IConnection = { host: connection.host };
  await authorize_seller_join(sellerConnection, {});
  // ─── 4. Seller submits approval request ───────────────────────────────────
  const approval = await generate_random_shopping_mall_seller_approvals_create(
    sellerConnection,
    {},
  );
  typia.assert(approval);
  // ─── 5. Admin approves seller ─────────────────────────────────────────────
  const approvedApproval =
    await api.functional.shoppingMall.admin.sellerApprovals.update(
      adminConnection,
      {
        approvalId: approval.id,
        body: {
          status: "approved",
          rejection_reason: null,
        } satisfies IShoppingMallSellerApproval.IUpdate,
      },
    );
  typia.assert(approvedApproval);
  // ─── 6. Seller creates a product ──────────────────────────────────────────
  const product = await generate_random_shopping_mall_seller_products_create(
    sellerConnection,
    {
      body: {
        categoryId: category.id,
      },
    },
  );
  typia.assert(product);
  // ─── 7. Seller creates a variant ──────────────────────────────────────────
  const variant =
    await generate_random_shopping_mall_seller_products_variants_create(
      sellerConnection,
      {
        params: { productId: product.id },
      },
    );
  typia.assert(variant);
  // ─── 8. Seller adds inventory ─────────────────────────────────────────────
  const inventoryRecord =
    await generate_random_shopping_mall_seller_products_variants_inventory_records_create(
      sellerConnection,
      {
        params: { productId: product.id, variantId: variant.id },
        body: { quantity: 50 },
      },
    );
  typia.assert(inventoryRecord);
  // ─── 9. Customer A joins ──────────────────────────────────────────────────
  const customerAConnection: api.IConnection = { host: connection.host };
  await authorize_customer_join(customerAConnection, {});
  // ─── 10. Customer A places an order ───────────────────────────────────────
  const order = await generate_random_shopping_mall_customer_orders_create(
    customerAConnection,
    {
      body: {
        items: [
          {
            product_variant_id: variant.id,
            quantity: 1,
          },
        ],
      },
    },
  );
  typia.assert(order);
  // Extract the order item id
  const orderItem = order.items[0]!;
  // ─── 11. Seller creates shipment (this also assigns items and marks them shipped) ─
  const shipment =
    await generate_random_shopping_mall_seller_orders_shipments_create(
      sellerConnection,
      {
        params: { orderId: order.id },
        body: {
          orderItemIds: [orderItem.id],
        },
      },
    );
  typia.assert(shipment);
  // ─── 12. Customer A creates a review (order item must be delivered) ────────
  const review =
    await generate_random_shopping_mall_customer_products_reviews_create(
      customerAConnection,
      {
        params: { productId: product.id },
        body: {
          order_item_id: orderItem.id,
          rating: 5,
          body: "Great product!",
        },
      },
    );
  typia.assert(review);
  // Extract reviewId and snapshotId from the auto-created first snapshot
  const reviewId = review.id;
  const firstSnapshot = review.snapshots[0]!;
  const snapshotId = firstSnapshot.id;
  // ─── 13. Customer B joins ─────────────────────────────────────────────────
  const customerBConnection: api.IConnection = { host: connection.host };
  await authorize_customer_join(customerBConnection, {});
  // ─── 14. Customer B attempts to access Customer A's snapshot — MUST get 403 ─
  await TestValidator.httpError(
    "Customer B must be denied access to Customer A's review snapshot",
    403,
    async () => {
      await api.functional.shoppingMall.customer.products.reviews.snapshots.at(
        customerBConnection,
        {
          productId: product.id,
          reviewId: reviewId,
          snapshotId: snapshotId,
        },
      );
    },
  );
  // ─── 15. Customer A CAN access her own snapshot — positive check ──────────
  const snapshot =
    await api.functional.shoppingMall.customer.products.reviews.snapshots.at(
      customerAConnection,
      {
        productId: product.id,
        reviewId: reviewId,
        snapshotId: snapshotId,
      },
    );
  typia.assert(snapshot);
  TestValidator.equals("snapshot id matches", snapshot.id, snapshotId);
  TestValidator.equals("review id matches", snapshot.reviewId, reviewId);
}

