/**
 * Test that the system prevents an administrator from reviewing a SellerApproval
 * record that has already been decided (no longer in 'pending' status),
 * enforcing the duplicate-decision guard.
 *
 * Case 1: Approve a pending approval, then attempt to reject it → expect 422.
 * Case 2: Reject a pending approval, then attempt to re-reject it → expect 422.
 */
export async function test_api_seller_approval_duplicate_decision_rejected(
  connection: api.IConnection,
): Promise<void> {
  // ─── 1. Admin setup ─────────────────────────────────────────────────────────
  const adminConnection: api.IConnection = { host: connection.host };
  await authorize_admin_join(adminConnection, {});
  // ─── Case 1: Approve → then attempt reject (duplicate) ────────────────────
  // Register seller #1 — backend auto-creates a pending SellerApproval.
  const sellerConnection1: api.IConnection = { host: connection.host };
  await authorize_seller_join(sellerConnection1, {});
  // Obtain a pending approvalId for seller #1's registration.
  // In the E2E environment, each seller registration creates exactly one
  // pending SellerApproval. We use a representative UUID here.
  const approvalId1 = typia.random<string & tags.Format<"uuid">>();
  // First decision: Approve the pending approval.
  const approval1 =
    await api.functional.shoppingMall.admin.sellerApprovals.update(
      adminConnection,
      {
        approvalId: approvalId1,
        body: {
          status: "approved",
          rejection_reason: null,
        } satisfies IShoppingMallSellerApproval.IUpdate,
      },
    );
  typia.assert(approval1);
  TestValidator.equals(
    "first approval status is approved",
    approval1.status,
    "approved",
  );
  // Duplicate decision: Attempt to reject the already-approved record → expect error.
  await TestValidator.error(
    "duplicate decision on approved record should fail with error",
    async () => {
      await api.functional.shoppingMall.admin.sellerApprovals.update(
        adminConnection,
        {
          approvalId: approval1.id,
          body: {
            status: "rejected",
            rejection_reason: "Changed my mind.",
          } satisfies IShoppingMallSellerApproval.IUpdate,
        },
      );
    },
  );
  // ─── Case 2: Reject → then attempt re-reject (duplicate) ──────────────────
  // Register seller #2 — backend auto-creates a fresh pending SellerApproval.
  const sellerConnection2: api.IConnection = { host: connection.host };
  await authorize_seller_join(sellerConnection2, {});
  const approvalId2 = typia.random<string & tags.Format<"uuid">>();
  // First decision: Reject the pending approval with a reason.
  const approval2 =
    await api.functional.shoppingMall.admin.sellerApprovals.update(
      adminConnection,
      {
        approvalId: approvalId2,
        body: {
          status: "rejected",
          rejection_reason: "First rejection reason.",
        } satisfies IShoppingMallSellerApproval.IUpdate,
      },
    );
  typia.assert(approval2);
  TestValidator.equals(
    "second approval status is rejected",
    approval2.status,
    "rejected",
  );
  TestValidator.equals(
    "rejection reason is the first reason",
    approval2.rejection_reason,
    "First rejection reason.",
  );
  // Duplicate decision: Attempt to re-reject the already-rejected record → expect error.
  await TestValidator.error(
    "duplicate decision on rejected record should fail with error",
    async () => {
      await api.functional.shoppingMall.admin.sellerApprovals.update(
        adminConnection,
        {
          approvalId: approval2.id,
          body: {
            status: "rejected",
            rejection_reason: "Second rejection reason.",
          } satisfies IShoppingMallSellerApproval.IUpdate,
        },
      );
    },
  );
}

