export async function test_api_order_item_force_cancel_already_cancelled_returns_error(
  connection: api.IConnection,
): Promise<void> {
  // 1. Register a superAdmin
  const superAdminConnection: api.IConnection = { host: connection.host };
  await authorize_super_admin_join(superAdminConnection, {});
  // 2. Register an admin
  const adminConnection: api.IConnection = { host: connection.host };
  await authorize_admin_join(adminConnection, {});
  // 3. Register a seller
  const sellerConnection: api.IConnection = { host: connection.host };
  await authorize_seller_join(sellerConnection, {});
  // 4. Register a customer
  const customerConnection: api.IConnection = { host: connection.host };
  await authorize_customer_join(customerConnection, {});
  // 5. Seller submits an approval request
  const approval = await generate_random_shopping_mall_seller_approvals_create(
    sellerConnection,
    { body: {} },
  );
  typia.assert(approval);
  // 6. Admin approves the seller
  const updatedApproval =
    await api.functional.shoppingMall.admin.sellerApprovals.update(
      adminConnection,
      {
        approvalId: approval.id,
        body: {
          status: "approved",
          rejection_reason: null,
        } satisfies IShoppingMallSellerApproval.IUpdate,
      },
    );
  typia.assert(updatedApproval);
  // 7. Admin creates a category
  const category = await generate_random_shopping_mall_admin_categories_create(
    adminConnection,
    { body: {} },
  );
  typia.assert(category);
  // 8. Seller creates a product with the created category
  const product = await generate_random_shopping_mall_seller_products_create(
    sellerConnection,
    {
      body: {
        categoryId: category.id,
      },
    },
  );
  typia.assert(product);
  // 9. Seller creates a variant
  const variant =
    await generate_random_shopping_mall_seller_products_variants_create(
      sellerConnection,
      {
        params: { productId: product.id },
        body: {},
      },
    );
  typia.assert(variant);
  // 10. Seller adds inventory (positive quantity to allow order placement)
  const inventoryRecord =
    await generate_random_shopping_mall_seller_products_variants_inventory_records_create(
      sellerConnection,
      {
        params: { productId: product.id, variantId: variant.id },
        body: { quantity: 10 },
      },
    );
  typia.assert(inventoryRecord);
  // 11. Customer places an order
  const order = await generate_random_shopping_mall_customer_orders_create(
    customerConnection,
    {
      body: {
        items: [
          {
            product_variant_id: variant.id,
            quantity: 1,
          },
        ],
      },
    },
  );
  typia.assert(order);
  // Get the first order item
  const orderItem = order.items[0];
  typia.assertGuard(orderItem!);
  // 12. SuperAdmin force-cancels the order item the first time - should succeed
  const cancelledItem =
    await api.functional.shoppingMall.superAdmin.orders.items.forceCancel(
      superAdminConnection,
      {
        orderId: order.id,
        itemId: orderItem.id,
        body: {
          reason: "Force cancelling for test - first attempt",
        } satisfies IShoppingMallOrderItem.IForceCancel,
      },
    );
  typia.assert(cancelledItem);
  TestValidator.equals(
    "item status after first force-cancel",
    cancelledItem.status,
    "cancelled",
  );
  // 13. SuperAdmin attempts to force-cancel the same item again - should fail with 422
  await TestValidator.httpError(
    "duplicate force-cancel on already cancelled item should return 422",
    422,
    async () => {
      await api.functional.shoppingMall.superAdmin.orders.items.forceCancel(
        superAdminConnection,
        {
          orderId: order.id,
          itemId: orderItem.id,
          body: {
            reason: "Force cancelling for test - second attempt (should fail)",
          } satisfies IShoppingMallOrderItem.IForceCancel,
        },
      );
    },
  );
}

