export async function test_api_order_item_force_refund_terminal_state_rejected(
  connection: api.IConnection,
): Promise<void> {
  // =========================================================================
  // 1. Admin setup - join
  // =========================================================================
  const adminConnection: api.IConnection = { host: connection.host };
  await authorize_admin_join(adminConnection, {
    body: {
      email: typia.random<string & tags.Format<"email">>(),
      password: RandomGenerator.alphaNumeric(16),
    },
  });
  // =========================================================================
  // 2. Seller setup - join
  // =========================================================================
  const sellerConnection: api.IConnection = { host: connection.host };
  await authorize_seller_join(sellerConnection, {
    body: {
      email: typia.random<string & tags.Format<"email">>(),
      password: RandomGenerator.alphaNumeric(16),
      shop_name: RandomGenerator.name(),
      href: typia.random<string & tags.Format<"uri">>(),
      referrer: typia.random<string & tags.Format<"uri">>(),
    },
  });
  // =========================================================================
  // 3. Seller submits approval request
  // =========================================================================
  const approval = await generate_random_shopping_mall_seller_approvals_create(
    sellerConnection,
    { body: {} },
  );
  typia.assert(approval);
  // =========================================================================
  // 4. Admin approves seller
  // =========================================================================
  const approvedApproval =
    await api.functional.shoppingMall.admin.sellerApprovals.update(
      adminConnection,
      {
        approvalId: approval.id,
        body: {
          status: "approved",
          rejection_reason: null,
        } satisfies IShoppingMallSellerApproval.IUpdate,
      },
    );
  typia.assert(approvedApproval);
  // =========================================================================
  // 5. Admin creates a product category
  // =========================================================================
  const category = await generate_random_shopping_mall_admin_categories_create(
    adminConnection,
    {
      body: {
        name: RandomGenerator.name(),
        description: RandomGenerator.paragraph({ sentences: 2 }),
      },
    },
  );
  typia.assert(category);
  // =========================================================================
  // 6. Seller creates a product listing
  // =========================================================================
  const product = await generate_random_shopping_mall_seller_products_create(
    sellerConnection,
    {
      body: {
        name: RandomGenerator.name(),
        description: RandomGenerator.paragraph({ sentences: 3 }),
        base_price: 10000,
        categoryId: category.id,
      },
    },
  );
  typia.assert(product);
  // =========================================================================
  // 7. Seller creates a product variant
  // =========================================================================
  const variant =
    await generate_random_shopping_mall_seller_products_variants_create(
      sellerConnection,
      {
        params: { productId: product.id },
        body: {
          sku: `SKU-${RandomGenerator.alphaNumeric(12)}`,
          priceOverride: null,
          options: [
            {
              key: "color",
              value: "red",
              sequence: 0,
            },
          ],
        },
      },
    );
  typia.assert(variant);
  // =========================================================================
  // 8. Seller adds inventory stock to the product variant
  // =========================================================================
  const inventoryRecord =
    await generate_random_shopping_mall_seller_products_variants_inventory_records_create(
      sellerConnection,
      {
        params: { productId: product.id, variantId: variant.id },
        body: {
          quantity: 10,
          note: "Initial stock for test",
        },
      },
    );
  typia.assert(inventoryRecord);
  // =========================================================================
  // 9. Customer setup - join
  // =========================================================================
  const customerConnection: api.IConnection = { host: connection.host };
  await authorize_customer_join(customerConnection, {
    body: {
      email: typia.random<string & tags.Format<"email">>(),
      password: RandomGenerator.alphaNumeric(16),
      nickname: RandomGenerator.name(1),
      phone: null,
      href: typia.random<string & tags.Format<"uri">>(),
      referrer: typia.random<string & tags.Format<"uri">>(),
    },
  });
  // =========================================================================
  // 10. Customer places an order (order item starts in 'paid' status)
  // =========================================================================
  const order = await generate_random_shopping_mall_customer_orders_create(
    customerConnection,
    {
      body: {
        recipient_name: RandomGenerator.name(),
        recipient_phone: RandomGenerator.mobile(),
        shipping_address_line1: "123 Test Street",
        shipping_address_line2: null,
        shipping_city: "Seoul",
        shipping_state: null,
        shipping_postal_code: "12345",
        shipping_country: "KR",
        items: [
          {
            product_variant_id: variant.id,
            quantity: 1,
          },
        ],
      },
    },
  );
  typia.assert(order);
  const orderItem = order.items[0];
  typia.assertGuard(orderItem!);
  // =========================================================================
  // 11. Seller creates a shipment for the order
  //     (orderItemIds included transitions item from 'paid' → 'shipped')
  // =========================================================================
  const shipment =
    await generate_random_shopping_mall_seller_orders_shipments_create(
      sellerConnection,
      {
        params: { orderId: order.id },
        body: {
          carrier: "TestCarrier",
          trackingNumber: `TRK-${RandomGenerator.alphaNumeric(10)}`,
          orderItemIds: [orderItem.id],
          shippedAt: new Date(
            Date.now() - 2 * 24 * 60 * 60 * 1000,
          ).toISOString(),
          estimatedDeliveryAt: new Date(
            Date.now() + 24 * 60 * 60 * 1000,
          ).toISOString(),
        },
      },
    );
  typia.assert(shipment);
  // =========================================================================
  // 12. Seller updates shipment with delivered_at context
  //     (shipped_at in the past signals delivery progression)
  // =========================================================================
  const updatedShipment =
    await api.functional.shoppingMall.seller.orders.shipments.update(
      sellerConnection,
      {
        orderId: order.id,
        shipmentId: shipment.id,
        body: {
          carrier: "TestCarrier",
          tracking_number: shipment.tracking_number,
          shipped_at: new Date(
            Date.now() - 3 * 24 * 60 * 60 * 1000,
          ).toISOString(),
          estimated_delivery_at: new Date(
            Date.now() - 1 * 24 * 60 * 60 * 1000,
          ).toISOString(),
        } satisfies IShoppingMallShipment.IUpdate,
      },
    );
  typia.assert(updatedShipment);
  // =========================================================================
  // 13. Admin performs FIRST force-refund
  //     (item must be in 'delivered' or allowed status → transitions to 'refunded')
  // =========================================================================
  const refundedItem =
    await api.functional.shoppingMall.admin.orders.items.forceRefund(
      adminConnection,
      {
        orderId: order.id,
        itemId: orderItem.id,
      },
    );
  typia.assert(refundedItem);
  TestValidator.equals(
    "first force-refund result status is refunded",
    refundedItem.status,
    "refunded",
  );
  // =========================================================================
  // 14. Admin performs SECOND force-refund on already-refunded item
  //     → Expects 422 Unprocessable Entity
  // =========================================================================
  await TestValidator.httpError(
    "second force-refund on already-refunded item must return 422",
    422,
    async () => {
      await api.functional.shoppingMall.admin.orders.items.forceRefund(
        adminConnection,
        {
          orderId: order.id,
          itemId: orderItem.id,
        },
      );
    },
  );
}

