export async function test_api_order_admin_force_cancel_with_reason_inventory_restored(
  connection: api.IConnection,
): Promise<void> {
  // Step 1: Admin joins and authenticates
  const adminConnection: api.IConnection = { host: connection.host };
  await authorize_admin_join(adminConnection, {});
  // Step 2: Admin creates a product category
  const category = await generate_random_shopping_mall_admin_categories_create(
    adminConnection,
    {
      body: {
        name: RandomGenerator.alphaNumeric(8),
        description: RandomGenerator.paragraph({ sentences: 2 }),
      },
    },
  );
  typia.assert(category);
  // Step 3: Seller joins and authenticates
  const sellerConnection: api.IConnection = { host: connection.host };
  await authorize_seller_join(sellerConnection, {});
  // Step 4: Seller submits approval request
  const approval = await generate_random_shopping_mall_seller_approvals_create(
    sellerConnection,
    {},
  );
  typia.assert(approval);
  // Step 5: Admin approves the seller
  const approvedApproval =
    await api.functional.shoppingMall.admin.sellerApprovals.update(
      adminConnection,
      {
        approvalId: approval.id,
        body: {
          status: "approved",
          rejection_reason: null,
        } satisfies IShoppingMallSellerApproval.IUpdate,
      },
    );
  typia.assert(approvedApproval);
  // Step 6: Seller creates a product
  const product = await generate_random_shopping_mall_seller_products_create(
    sellerConnection,
    {
      body: {
        name: RandomGenerator.paragraph({ sentences: 2 }),
        description: RandomGenerator.paragraph({ sentences: 3 }),
        base_price: 10000,
        categoryId: category.id,
      },
    },
  );
  typia.assert(product);
  // Step 7: Seller creates a variant (let utility fill in random options)
  const variant =
    await generate_random_shopping_mall_seller_products_variants_create(
      sellerConnection,
      {
        params: { productId: product.id },
        body: {
          sku: RandomGenerator.alphaNumeric(12),
        },
      },
    );
  typia.assert(variant);
  // Step 8: Seller adds 5 units of initial stock
  const inventoryRecord =
    await generate_random_shopping_mall_seller_products_variants_inventory_records_create(
      sellerConnection,
      {
        params: { productId: product.id, variantId: variant.id },
        body: {
          quantity: 5,
          note: "Initial stock",
        },
      },
    );
  typia.assert(inventoryRecord);
  // Step 9: Customer joins and authenticates
  const customerConnection: api.IConnection = { host: connection.host };
  await authorize_customer_join(customerConnection, {});
  // Step 10: Customer places an order for 3 units of the variant
  const order = await generate_random_shopping_mall_customer_orders_create(
    customerConnection,
    {
      body: {
        recipient_name: RandomGenerator.name(),
        recipient_phone: RandomGenerator.mobile(),
        shipping_address_line1: RandomGenerator.paragraph({ sentences: 1 }),
        shipping_address_line2: null,
        shipping_city: RandomGenerator.alphabets(6),
        shipping_state: null,
        shipping_postal_code: RandomGenerator.alphaNumeric(5),
        shipping_country: "KR",
        items: [
          {
            product_variant_id: variant.id,
            quantity: 3,
          },
        ],
      },
    },
  );
  typia.assert(order);
  TestValidator.equals(
    "order status is paid after placement",
    order.status,
    "paid",
  );
  TestValidator.predicate("order has items", order.items.length > 0);
  // Step 11: Admin force-cancels the order with an optional reason string
  const cancelledOrder =
    await api.functional.shoppingMall.admin.orders.forceCancel(
      adminConnection,
      {
        orderId: order.id,
        body: {
          reason: "Policy violation - order placed with fraudulent account",
        } satisfies IShoppingMallOrder.IForceCancel,
      },
    );
  typia.assert(cancelledOrder);
  // Step 12: Validate the cancelled order status
  TestValidator.equals(
    "order status is cancelled after force-cancel",
    cancelledOrder.status,
    "cancelled",
  );
  // Validate all items have been cancelled
  for (const item of cancelledOrder.items) {
    TestValidator.equals(
      "each order item status is cancelled",
      item.status,
      "cancelled",
    );
  }
  // Validate order integrity — items preserved
  TestValidator.predicate(
    "cancelled order has items",
    cancelledOrder.items.length > 0,
  );
  // Validate the order id matches the original
  TestValidator.equals(
    "cancelled order id matches original",
    cancelledOrder.id,
    order.id,
  );
}

