      where: whereInput,
      select: {
        id: true,
        ip: true,
        href: true,
        referrer: true,
        created_at: true,
        expired_at: true,
      },
      orderBy: { created_at: "desc" },
      skip,
      take: limit,
    });
  // 4. Count total
  const total = await MyGlobal.prisma.shopping_mall_customer_sessions.count({
    where: whereInput,
  });
  // 5. Map to ISummary
  const checkNow = new Date();
  const data: IShoppingMallCustomerSession.ISummary[] = sessions.map(
    (s) =>
      ({
        id: s.id,
        ip: s.ip,
        href: s.href,
        referrer: s.referrer,
        is_active: s.expired_at > checkNow,
        created_at: s.created_at.toISOString(),
        expired_at: s.expired_at.toISOString(),
      }) satisfies IShoppingMallCustomerSession.ISummary,
  );
  return {
    pagination: {
      current: page,
      limit: limit,
      records: total,
      pages: Math.ceil(total / limit),
    } satisfies IPage.IPagination,
    data,
  };
}

