    props.body.grade === "super"
      ? { id: { in: superAdminIdList } }
      : props.body.grade === "regular"
        ? { id: { notIn: superAdminIdList } }
        : {};
  // Build created_at range filter (combine both bounds into one object)
  const hasFrom =
