    ...(props.body.actorType !== undefined && props.body.actorType !== null
      ? { actor_type: props.body.actorType }
      : {}),
    ...(props.body.includeDeleted !== true ? { deleted_at: null } : {}),
    ...createdAtFilter,
    ...gradeFilter,
  } satisfies Prisma.shopping_mall_adminsWhereInput;
