          in: affectedCategoryIds,
        },
      },
      data: {
        shopping_mall_category_id: null,
      },
    });
    // 3b: Delete the category (cascade removes children automatically)
    await tx.shopping_mall_categories.delete({
      where: { id: props.categoryId },
