      where: {
        id: props.shipmentItemId,
        shopping_mall_shipment_id: props.shipmentId,
      },
      select: { id: true },
    });
    if (shipmentItem === null) {
      throw new HttpException(
        "Shipment item not found or does not belong to the specified shipment",
