@Controller("/shoppingMall/products/:productId/images")
export class ShoppingmallProductsImagesController {
  /**
   * Reorder the display sequence of images associated with a specific product.
   *
   * This operation allows the owning seller to change the display order of all images currently attached to a product. The seller provides a new ordered sequence of image IDs, and the system updates the `sequence` field of each image record in the `shopping_mall_product_images` table to reflect the new arrangement. The image placed first in the provided sequence becomes the main thumbnail (lowest sequence value), which is the image shown in product listing views such as search results and category pages. All remaining images are assigned ascending sequence values according to the provided order.
   *
   * Access to this operation is strictly limited to the seller who owns the product. Any attempt by a different seller to reorder images on a product they do not own will be rejected. The system validates product ownership by cross-referencing the authenticated seller's identity against the `shopping_mall_seller_id` field on the `shopping_mall_products` record identified by `productId`. An error is returned if the product does not exist, has been deleted (`deleted_at` is not null), or belongs to a different seller.
   *
   * Reordering images constitutes a product edit. Immediately after the sequence is updated, the system automatically creates a new `shopping_mall_product_snapshots` record capturing the full current state of the product, including the new image order. This ensures the visual configuration of the product at every point in time is preserved for historical review, dispute resolution, and order records. The seller cannot reorder images without a snapshot being created as a result.
   *
   * The request body must list all existing image IDs for the product in the desired new order. If an image ID is omitted or an unknown ID is provided, the request is rejected to prevent accidental data loss or inconsistency. After a successful reorder, the full updated list of product images is returned in the new display order.
   *
   * Pre-requisite: The caller must be authenticated as the seller who owns the product identified by `productId`. The product must be active (not deleted).
   *
   * @param connection
   * @param productId The UUID of the product whose images are to be reordered.
   * @param body Ordered list of image IDs representing the desired new display sequence for the product's images.
   * @x-autobe-authorization-type null
   * @x-autobe-authorization-actor null
   * @x-autobe-specification 1. Authenticate the request and confirm the caller is a seller.
   * 2. Look up the product by `productId` in `shopping_mall_products`. Return 404 if not found or if `deleted_at` is not null.
   * 3. Validate that the authenticated seller's ID matches `shopping_mall_products.shopping_mall_seller_id`. Return 403 if not.
   * 4. Extract the ordered list of image IDs from the request body (`IShoppingMallProductImage.IReorder.imageIds`).
   * 5. Query `shopping_mall_product_images` WHERE `shopping_mall_product_id = productId` to retrieve all current image records.
   * 6. Validate that the provided list of image IDs exactly matches the set of current image IDs for the product (same count, no missing, no unknown IDs). Return 422 if validation fails.
   * 7. Within a database transaction:
   *    a. For each image ID in the provided ordered array, UPDATE `shopping_mall_product_images` SET `sequence = index` (0-based or 1-based, consistent with system convention) WHERE `id = imageId`.
   *    b. Update `shopping_mall_products.updated_at` to the current timestamp.
   *    c. Create a new `shopping_mall_product_snapshots` record capturing the full product state at this moment, including all variant states and the new image sequence.
   * 8. Commit the transaction.
   * 9. Query `shopping_mall_product_images` WHERE `shopping_mall_product_id = productId` ORDER BY `sequence ASC` and return the result as `IShoppingMallProductImage.IReorderResult`.
   * @nestia Generated by Nestia - https://github.com/samchon/nestia
   */
  @TypedRoute.Patch()
  public async reorder(
    @TypedParam("productId")
    productId: string & tags.Format<"uuid">,
    @TypedBody()
    body: IShoppingMallProductImage.IReorder,
  ): Promise<IShoppingMallProductImage.IReorderResult> {
    try {
      return await patchShoppingMallProductsProductIdImages({
        productId,
        body,
      });
    } catch (error) {
      console.log(error);
      throw error;
    }
  }

  /**
   * Retrieve a single product image record by its identifier, scoped to a specific product.
   *
   * This operation returns the full details of a product image associated with the specified product. The `shopping_mall_product_images` table stores each image as an ordered visual asset attached to a product listing. Each image record holds the image URL pointing to the hosted file (e.g., a CDN or object storage URL) and a `sequence` value that controls the display order within the product's image gallery — lower sequence values are displayed first.
   *
   * The image with the lowest sequence value (first position) is treated as the main thumbnail shown in product listing views, search results, and category pages. All other images are displayed in ascending sequence order on the product detail page.
   *
   * This endpoint is accessible to all users — customers browsing a product detail page, guests, sellers, and administrators — as long as the associated product exists and has not been deleted. Product images are part of the publicly accessible product detail content. According to the platform's product visibility model, image retrieval requires only that the parent product is active (i.e., `deleted_at` IS NULL in `shopping_mall_products`). Write operations on images (uploading, reordering, deleting) are restricted to the owning seller.
   *
   * Before calling this endpoint, the caller must know both the product's unique identifier and the image's unique identifier. These identifiers can be obtained by first calling `GET /shoppingMall/products/{productId}` to retrieve product details including its associated images, or by listing product images for the given product.
   *
   * This endpoint does not modify any data. It is a read-only operation that reflects the current state of the image record in the `shopping_mall_product_images` table.
