   * 4. Look up the image in shopping_mall_product_images where id = imageId AND shopping_mall_product_id = productId. If not found (either the image does not exist or does not belong to the specified product), return 404 Not Found.
   * 5. Authorization check: If the caller is a seller, verify that shopping_mall_products.shopping_mall_seller_id matches the authenticated seller's ID. If not, return 403 Forbidden. Admins and super admins may bypass this check.
   * 6. Return the image record including: id, shopping_mall_product_id, url, sequence, created_at.
   * 7. No joins to other tables are required beyond the product ownership verification query.
   * @nestia Generated by Nestia - https://github.com/samchon/nestia
   */
  @TypedRoute.Get(":imageId")
  public async at(
    @TypedParam("productId")
    productId: string & tags.Format<"uuid">,
    @TypedParam("imageId")
    imageId: string & tags.Format<"uuid">,
  ): Promise<IShoppingMallProductImage> {
    try {
      return await getShoppingMallProductsProductIdImagesImageId({
        productId,
        imageId,
      });
    } catch (error) {
