   */
  @TypedRoute.Patch()
  public async index(
    @SellerAuth()
    seller: SellerPayload,
    @TypedParam("productId")
    productId: string & tags.Format<"uuid">,
    @TypedBody()
    body: IShoppingMallProductSnapshot.IRequest,
  ): Promise<IPageIShoppingMallProductSnapshot.ISummary> {
    try {
      return await patchShoppingMallSellerProductsProductIdSnapshots({
        seller,
        productId,
        body,
      });
    } catch (error) {
      console.log(error);
      throw error;
    }
  }

  /**
   * Retrieve the full details of a specific immutable product snapshot identified by the product ID and snapshot ID.
   *
   * Product snapshots (stored in `shopping_mall_product_snapshots`) are point-in-time records automatically created whenever a seller edits any editable field of a product. Each snapshot captures the product's name, description, base price, category association, the complete ordered set of product images (`shopping_mall_product_snapshot_images`), and the full state of every product variant that existed at that moment (`shopping_mall_product_snapshot_skuses` with their option key-value pairs in `shopping_mall_product_snapshot_skus_options`). Snapshots are strictly immutable once created and are never modified or deleted — even after the owning product is removed from the platform.
   *
   * This endpoint returns the full details of a single snapshot, allowing the caller to reconstruct the exact product state at the moment of the snapshot. The response includes all sub-records: the ordered image list and all variant SKU entries with their complete option combinations.
   *
   * **Authorization**: Only sellers and administrators may access this endpoint. Customers are denied access regardless of context.
   * - A seller may only retrieve snapshots belonging to products they own. Attempting to access a snapshot for another seller's product results in a 403 Forbidden response.
   * - Administrators (including super administrators) may retrieve snapshots for any product on the platform, regardless of which seller owns or owned the product.
