   *    b. If approved, update the related `shopping_mall_order_items.status` to 'cancelled' and set its `updated_at`.
   *    c. Create a new `shopping_mall_cancellation_request_snapshots` record with:
   *       - `id`: new UUID
   *       - `cancellation_request_id`: the cancellation request's id
   *       - `status`: the decision ('approved' or 'rejected')
   *       - `reason`: the original `reason` text from the cancellation request (verbatim copy)
   *       - `created_at`: current timestamp
   *    d. Recalculate and update the parent order's `status` field in `shopping_mall_orders` based on the aggregate statuses of all its order items.
   * 7. Return the updated `shopping_mall_cancellation_requests` record (with nested snapshots if applicable).
   * @nestia Generated by Nestia - https://github.com/samchon/nestia
   */
  @TypedRoute.Put()
  public async update(
    @SellerAuth()
    seller: SellerPayload,
    @TypedParam("cancellationRequestId")
    cancellationRequestId: string & tags.Format<"uuid">,
    @TypedBody()
    body: IShoppingMallCancellationRequest.IUpdate,
  ): Promise<IShoppingMallCancellationRequest> {
    try {
      return await putShoppingMallSellerCancellationRequestsCancellationRequestId(
        {
          seller,
          cancellationRequestId,
          body,
        },
      );
    } catch (error) {
      console.log(error);
      throw error;
    }
