import { IShoppingMallReview } from "../../../../api/structures/IShoppingMallReview";
import { CustomerAuth } from "../../../../decorators/CustomerAuth";
import { CustomerPayload } from "../../../../decorators/payload/CustomerPayload";
import { patchShoppingMallCustomerReviews } from "../../../../providers/patchShoppingMallCustomerReviews";

@Controller("/shoppingMall/customer/reviews")
export class ShoppingmallCustomerReviewsController {
  /**
   * Retrieve a filtered and paginated list of customer reviews on the shopping mall platform.
   *
   * This operation returns a paginated collection of purchase-verified reviews stored in the `shopping_mall_reviews` table. Each review is anchored to a specific order item (`shopping_mall_order_items`) that qualifies it as purchase-verified, ensuring only customers who actually received the product can write a review. Reviews carry a mandatory star rating (integer 1–5) and an optional free-text body field.
   *
   * By default, only active (non-deleted) reviews are included in the results. Reviews that have been removed by their authors are excluded from the public listing, as indicated by the `deleted_at` field on the `shopping_mall_reviews` record. Administrator actors may request deleted reviews for audit or dispute resolution purposes.
   *
