import { postShoppingMallSellerApprovals } from "../../../../providers/postShoppingMallSellerApprovals";

@Controller("/shoppingMall/seller/approvals")
export class ShoppingmallSellerApprovalsController {
  /**
   * Submit a new seller approval request to the platform for administrator review.
   *
   * This operation allows a registered seller to submit a new approval request, creating a `SellerApproval` record with `pending` status in the platform. Every seller must have an approved status before they can list products, manage inventory, or accept orders on the platform. The approval record captures the submission timestamp, the current approval status, and any rejection reason recorded by the reviewing administrator.
   *
   * The typical use case for this endpoint is when a seller whose previous registration request has been `rejected` wants to resubmit their application for another round of administrator review. When a seller completes their initial registration, an approval record is created automatically by the system; this endpoint is therefore primarily used for resubmissions after rejection.
   *
   * Business rules enforced by this operation:
   * - A seller whose current approval request is still in `pending` status cannot create a new approval request. They must wait for a decision from an administrator before resubmitting.
   * - A seller who is already `approved` does not need to submit another request and cannot do so.
   * - Only sellers whose most recent approval record is in `rejected` status may invoke this endpoint to create a new `pending` approval request.
   *
   * Upon successful creation, the new approval record is returned with a `pending` status. Administrators can then retrieve and review pending approval records, making approve or reject decisions via the corresponding admin-facing endpoints. The complete history of all approval records for each seller is preserved and never deleted, ensuring a full audit trail of every registration attempt and administrative decision.
   *
   * Related API operations:
   * - `PATCH /approvals` — List and search seller approval records (admin)
   * - `GET /approvals/{approvalId}` — Retrieve a specific approval record (seller or admin)
   * - `PUT /approvals/{approvalId}/approve` — Approve a pending seller registration (admin)
   * - `PUT /approvals/{approvalId}/reject` — Reject a pending seller registration (admin)
   *
   * @param connection
   * @param body Seller approval request submission data, including any supporting profile information for the administrator's review.
   * @x-autobe-authorization-type null
   * @x-autobe-authorization-actor seller
   * @x-autobe-specification 1. Authenticate the requesting actor as a seller using the session token.
   * 2. Query the shopping_mall_sellers table to verify the seller exists and is not banned (is_banned = false).
   * 3. Find the most recent SellerApproval record associated with this seller.
   * 4. Validate resubmission eligibility:
   *    - If the most recent approval record has status 'pending', return HTTP 422 with a message indicating the seller must wait for a decision.
   *    - If the most recent approval record has status 'approved', return HTTP 422 with a message indicating the seller is already approved.
   *    - Only proceed if the most recent approval status is 'rejected' (or no prior approval exists for resubmission path).
   * 5. Create a new SellerApproval record:
   *    - Set status = 'pending'
   *    - Set seller reference to the authenticated seller's ID
   *    - Set submitted_at = current timestamp
   *    - Clear/null any rejection reason and reviewed_at from the new record
   * 6. Persist the new SellerApproval record to the database.
   * 7. Return the newly created SellerApproval record as IShoppingMallSellerApproval in the response body.
   *
   * Edge cases:
   * - If the seller account is suspended (is_suspended = true), the resubmission may still be allowed as suspension does not bar approval resubmission — only rejected status matters.
   * - If the seller account is banned (is_banned = true), reject the request with HTTP 403.
   * - Ensure atomicity: record creation should be within a single database transaction.
   * @nestia Generated by Nestia - https://github.com/samchon/nestia
   */
  @TypedRoute.Post()
  public async create(
    @SellerAuth()
    seller: SellerPayload,
    @TypedBody()
    body: IShoppingMallSellerApproval.ICreate,
  ): Promise<IShoppingMallSellerApproval> {
    try {
      return await postShoppingMallSellerApprovals({
        seller,
        body,
      });
    } catch (error) {
      console.log(error);
      throw error;
    }
  }

  /**
   * Retrieve a paginated and filtered list of seller approval records on the shopping mall platform.
   *
   * This operation provides administrators with comprehensive access to all seller approval records (`shopping_mall_seller_approvals`), enabling them to manage the seller registration workflow. The primary use case is for administrators to find and review pending seller registrations, but the endpoint also supports querying approved, rejected, and all historical records for audit and accountability purposes.
   *
   * Access is restricted to authenticated administrators (both regular and super administrators). Sellers cannot use this endpoint to list all approval records; they access only their own approval status through a dedicated self-service endpoint. Unauthenticated requests are rejected.
   *
   * The response is a paginated collection of seller approval summaries, each containing the approval status (`pending`, `approved`, `rejected`), submission timestamp, rejection reason (when applicable), review timestamp, the seller's identifying information (shop name, email), and the reviewing administrator's identity. This supports the accountability and audit trail requirements defined in the platform's data retention policy.
   *
   * Administrators typically filter by `status: "pending"` to identify registrations awaiting their decision. They can then navigate to the individual approval record to take action (approve or reject). The endpoint also supports date range filtering on submission date and text search on the seller's shop name or email, enabling efficient triage of large queues.
   *
   * The complete history of approval records is preserved, including multiple approval records for the same seller (from resubmissions after rejection). This history is never deleted and is always accessible to administrators for dispute resolution and accountability purposes, as required by platform data retention rules (section 145).
   *
   * Related operations:
   * - `GET /approvals/{approvalId}`: Retrieve the full detail of a specific seller approval record.
   * - `PUT /approvals/{approvalId}/approve`: Approve a pending seller registration.
   * - `PUT /approvals/{approvalId}/reject`: Reject a pending seller registration with a required reason.
   *
   * @param connection
   * @param body Search criteria and pagination options for filtering seller approval records.
   * @x-autobe-authorization-type null
   * @x-autobe-authorization-actor seller
   * @x-autobe-specification 1. Authentication: Verify the requester holds an active admin or super admin session. Reject with 401 if unauthenticated, 403 if the actor is not an admin.
   *
   * 2. Query the `shopping_mall_seller_approvals` table (joined with `shopping_mall_sellers` for shop_name and email) with the following filters from the request body:
   *    - `status` (optional): Filter by approval status ('pending', 'approved', 'rejected'). If omitted, return all statuses.
   *    - `sellerKeyword` (optional): Case-insensitive partial text match on seller shop_name or email (use trigram index or ILIKE).
   *    - `submittedAtFrom` / `submittedAtTo` (optional): Filter by submission date range on `created_at`.
   *    - `reviewedAtFrom` / `reviewedAtTo` (optional): Filter by review decision date range.
   *
   * 3. Apply pagination using the `page` and `limit` parameters from the request body. Default page = 1, default limit = 20. Calculate total count for pagination metadata.
   *
   * 4. Apply ordering: default order by `created_at` DESC (most recent submissions first). Optionally support ordering by `status` or `created_at` ASC/DESC based on sort parameters.
   *
   * 5. For each approval record, JOIN to `shopping_mall_sellers` to retrieve `shop_name`, `email`, `is_banned`, `is_suspended`. JOIN to `shopping_mall_admins` or `shopping_mall_super_admins` on the reviewer FK (if reviewed) to include reviewer identity.
   *
   * 6. Return paginated response with `pagination` metadata (total, current page, limit, total pages) and `data` array of approval summaries.
   *
   * 7. Edge cases:
   *    - If no records match the filter criteria, return empty `data` array with valid pagination metadata.
   *    - If `limit` exceeds a platform maximum (e.g., 100), clamp to the maximum value.
   *    - Ensure that deleted seller accounts (`deleted_at IS NOT NULL`) are still included in results since history must be preserved.
   * @nestia Generated by Nestia - https://github.com/samchon/nestia
   */
  @TypedRoute.Patch()
  public async index(
    @SellerAuth()
    seller: SellerPayload,
    @TypedBody()
    body: IShoppingMallSellerApproval.IRequest,
  ): Promise<IPageIShoppingMallSellerApproval.ISummary> {
    try {
      return await patchShoppingMallSellerApprovals({
        seller,
        body,
      });
    } catch (error) {
      console.log(error);
      throw error;
    }
  }

  /**
   * Retrieve detailed information about a specific seller approval record by its unique identifier.
   *
   * A SellerApproval is the authoritative record that determines whether a seller is permitted to operate on the platform. Every seller registration automatically generates a SellerApproval record, which functions as the formal gate controlling whether that seller may list products, accept orders, and conduct commerce on the platform. Until a SellerApproval is granted, the seller account exists on the platform but cannot perform any selling activities.
   *
   * This endpoint returns the full details of a single SellerApproval record, identified by its unique UUID. The record captures the following information:
   * - **Approval status**: The current administrative decision — `pending` (awaiting admin review), `approved` (seller granted platform access), or `rejected` (seller denied registration).
   * - **Submission date**: When the seller submitted their registration request, establishing the chronological audit trail.
   * - **Rejection reason**: When an administrator rejects a registration, a written explanation is recorded so the seller understands the basis for denial. This field is null for non-rejected records.
   * - **Review date**: When an administrator made their decision (null if still pending).
   *
   * Since a seller may submit multiple registration requests over time (each rejection allows resubmission), a seller can have multiple SellerApproval records. Each record is independently identifiable by its UUID. The platform preserves the complete history of all approval decisions for accountability and dispute resolution purposes.
   *
   * Access is restricted to administrators (admin and superAdmin) for platform oversight and accountability purposes, and to the owning seller to view the status of their own registration attempt.
   *
