   * @nestia Generated by Nestia - https://github.com/samchon/nestia
   */
  @TypedRoute.Patch()
  public async index(
    @AdminAuth()
    admin: AdminPayload,
    @TypedBody()
    body: IShoppingMallSellerApproval.IRequest,
  ): Promise<IPageIShoppingMallSellerApproval.ISummary> {
    try {
      return await patchShoppingMallAdminSellerApprovals({
        admin,
        body,
      });
    } catch (error) {
      console.log(error);
      throw error;
    }
  }
